        f"<i>{fam['desc']}</i>"
    )

files.engine/pets.py:
"""Шаблоны питомцев: каталог, редактируемый из панели (IDEAS-100.md № 20).

Разделение, которое здесь важно не перепутать:

* `engine/familiars.py` — **механика**: три фиксированных спутника с
  боевыми бонусами, их герой заводит в боте;
* этот модуль — **редактируемый каталог** будущих видов, который админ
  наполняет сам. Именно он стоит за `PetTemplate` в серверной БД и за
  `store.settings["pet_templates"]` в браузерном стеке.

Пункт № 58 в своё время был снят как задача-фантом ровно потому, что
`core/pets.py` считали механикой; на деле это каталог. Поэтому здесь
нет боевых формул — только правила ключа, редкости и бонусов, общие для
обеих панелей. Валидация одна на два стека: раньше нормализация ключа и
разбор JSON-бонусов жили только в `core/pets.py`, и браузерная панель
не смогла бы принять шаблон по тем же правилам.
"""
import json
import re

TEMPLATES_KEY = "pet_templates"     # ключ в store.settings браузерного стека

RARITIES = ("common", "uncommon", "rare", "epic", "legendary")
RARITY_LABELS = {
    "common": "Обычный", "uncommon": "Необычный", "rare": "Редкий",
    "epic": "Эпический", "legendary": "Легендарный",
}
RARITY_ICONS = {
    "common": "⚪", "uncommon": "🟢", "rare": "🔵",
    "epic": "🟣", "legendary": "🟠",
}

FAMILIES = ("slime", "beast", "bird", "spirit", "construct")
FAMILY_LABELS = {
    "slime": "Слизни", "beast": "Звери", "bird": "Птицы",
    "spirit": "Духи", "construct": "Конструкты",
}

# Ключи бонусов, которые механика умеет читать (engine/familiars).
# Всё остальное в JSON допустимо, но помечается как «пока декоративный».
KNOWN_BONUSES = ("crit_bonus", "magic_bonus", "gold_to_stash_pct",
                 "vision_bonus", "berserk_bonus", "ambush_shield")


def normalize_key(value: str, fallback: str = "pet") -> str:
    """Стабильный ключ для колбэков и сохранений."""
    text = (value or "").strip().lower().replace(" ", "_")
    text = re.sub(r"[^a-z0-9а-яё_\-]+", "", text, flags=re.I)
    return text[:64] or fallback


def normalize_bonuses(value) -> str:
    """В хранилище всегда JSON-объект; мусор отклоняется явно."""
    if isinstance(value, dict):
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    raw = (value or "").strip() or "{}"
    parsed = json.loads(raw)
    if not isinstance(parsed, dict):
        raise ValueError("Бонусы должны быть JSON-объектом")
    return json.dumps(parsed, ensure_ascii=False, separators=(",", ":"))


def parse_bonuses(raw) -> dict:
    """Прочитать бонусы, не роняя экран на битой строке."""
    if isinstance(raw, dict):
        return raw
    try:
        parsed = json.loads(raw or "{}")
    except (ValueError, TypeError):
        return {}
    return parsed if isinstance(parsed, dict) else {}


def normalize_rarity(value: str) -> str:
    value = (value or "").strip().lower()
    return value if value in RARITIES else "common"


def normalize_family(value: str) -> str:
    value = (value or "").strip().lower()
    return value if value in FAMILIES else "slime"


def make_template(name: str, key: str = "", description: str = "",
                  family: str = "slime", rarity: str = "common",
                  bonuses="{}", image_url: str = "",
                  sort_order: int = 100, is_active: bool = True) -> dict:
    """Собрать корректный шаблон. Бросает ValueError на пустом имени."""
    name = (name or "").strip()
    if not name:
        raise ValueError("У питомца должно быть имя")
    return {
        "key": normalize_key(key or name),
        "name": name[:128],
        "description": (description or "").strip()[:500],
        "family": normalize_family(family),
        "rarity": normalize_rarity(rarity),
        "bonuses_json": normalize_bonuses(bonuses),
        "image_url": (image_url or "").strip()[:512],
        "sort_order": int(sort_order or 100),
        "is_active": bool(is_active),
    }


def templates(store) -> list:
    """Шаблоны браузерного стека. Битые записи отбрасываются."""
    raw = store.settings.get(TEMPLATES_KEY)
    if not isinstance(raw, list):
        raw = []
        store.settings[TEMPLATES_KEY] = raw
    out = []
    for row in raw:
        if isinstance(row, dict) and row.get("name"):
            out.append(row)
    return sorted(out, key=lambda r: (int(r.get("sort_order", 100)),
                                      r.get("name", "")))


def add(store, **kwargs) -> dict:
    """Добавить шаблон. Ключ уникален: повтор перезаписывает запись."""
    tpl = make_template(**kwargs)
    rows = [r for r in templates(store) if r.get("key") != tpl["key"]]
    rows.append(tpl)
    store.settings[TEMPLATES_KEY] = rows
    return tpl


def remove(store, key: str) -> bool:
    """Удалить шаблон по ключу."""
    rows = templates(store)
    left = [r for r in rows if r.get("key") != key]
    store.settings[TEMPLATES_KEY] = left
    return len(left) != len(rows)


def toggle(store, key: str) -> bool | None:
    """Включить/выключить шаблон. Возвращает новое состояние или None."""
    rows = templates(store)
    for row in rows:
        if row.get("key") == key:
            row["is_active"] = not row.get("is_active", True)
            store.settings[TEMPLATES_KEY] = rows
            return row["is_active"]
    return None


def describe_bonuses(raw) -> str:
    """Человеческая строка бонусов для карточки шаблона."""
    data = parse_bonuses(raw)
    if not data:
        return "без бонусов"
    parts = []
    for key, val in data.items():
        mark = "" if key in KNOWN_BONUSES else " (пока декоративный)"
        parts.append(f"{key}: {val}{mark}")
    return " · ".join(parts)

files.engine/runes.py:
"""Руны, гнёзда экипировки и рунические слова.

Каталоги рун и слов — **единственный источник правды** для обоих стеков:
`core/runes.py` реэкспортирует их отсюда. Вставка руны работает с любым
объектом, у которого есть поля `socket_1/socket_2` и `bonus_*`: и с
серверным `ItemInstance`, и с записью реестра `engine/items.py`
(для неё есть обёртка `insert_into_instance` ниже).
"""

SOCKETS = 2      # сколько гнёзд у предмета: больше — уже не «слово», а салат

RUNES = {
    "rune_fire": {
        "name": "Руна Огня",
        "icon": "🔥",
        "bonus_damage": 10,
        "bonus_hp": 0,
        "desc": "+10 к урону огнём",
    },
    "rune_iron": {
        "name": "Руна Стали",
        "icon": "🛡",
        "bonus_damage": 0,
        "bonus_defense": 15,
        "desc": "+15 к броне и защите",
    },
    "rune_void": {
        "name": "Руна Бездны",
        "icon": "🌑",
        "bonus_damage": 12,
        "bonus_luck": 5,
        "desc": "+12 урона тьмой и +5 к удаче",
    },
    "rune_light": {
        "name": "Руна Света",
        "icon": "✨",
        "bonus_hp": 30,
        "bonus_damage": 8,
        "desc": "+30 HP и +8 святого урона",
    },
}

RUNEWORDS = {
    frozenset(["rune_fire", "rune_iron"]): {
        "name": "Пламенная сталь",
        "bonus_damage": 20,
        "bonus_defense": 15,
        "desc": "Сверхпрочный сплав: +20 к урону и +15 к защите!",
    },
    frozenset(["rune_void", "rune_void"]): {
        "name": "Взор Бездны",
        "bonus_damage": 25,
        "bonus_luck": 12,
        "desc": "Взор из глубин: +25 к урону тьмы и +12 к удаче!",
    },
    frozenset(["rune_light", "rune_iron"]): {
        "name": "Благословение Рассвета",
        "bonus_hp": 60,
        "bonus_defense": 20,
        "desc": "Священные латы: +60 к макс. здоровью и +20 к защите!",
    },
    frozenset(["rune_fire", "rune_void"]): {
        "name": "Пепельное пламя",
        "bonus_damage": 30,
        "bonus_hp": 15,
        "desc": "Раскалённый пепел: +30 к урону и +15 HP!",
    },
}


def check_runeword(r1: str | None, r2: str | None) -> dict | None:
    if not r1 or not r2:
        return None
    pair = frozenset([r1, r2])
    return RUNEWORDS.get(pair)


def insert_rune(instance, rune_key: str, slot: int = 1) -> dict:
    """Вставить руну в свободное гнездо предмета."""
    if rune_key not in RUNES:
        return {"ok": False, "reason": "Неизвестная руна."}

    if slot == 1:
        instance.socket_1 = rune_key
    elif slot == 2:
        instance.socket_2 = rune_key
    else:
        return {"ok": False, "reason": "Неверный слот руны."}

    # Применяем базовые бонусы руны
    rdata = RUNES[rune_key]
    instance.bonus_damage = (instance.bonus_damage or 0) + rdata.get("bonus_damage", 0)
    instance.bonus_defense = (instance.bonus_defense or 0) + rdata.get("bonus_defense", 0)
    instance.bonus_hp = (instance.bonus_hp or 0) + rdata.get("bonus_hp", 0)
    instance.bonus_luck = (instance.bonus_luck or 0) + rdata.get("bonus_luck", 0)

    # Проверяем составление рунического слова
    s1 = getattr(instance, "socket_1", None)
    s2 = getattr(instance, "socket_2", None)
    rw = check_runeword(s1, s2)
    formed_runeword = None
    if rw:
        instance.runeword = rw["name"]
        instance.bonus_damage = (instance.bonus_damage or 0) + rw.get("bonus_damage", 0)
        instance.bonus_defense = (instance.bonus_defense or 0) + rw.get("bonus_defense", 0)
        instance.bonus_hp = (instance.bonus_hp or 0) + rw.get("bonus_hp", 0)
        formed_runeword = rw["name"]

    return {
        "ok": True,
        "rune": rdata["name"],
        "runeword": formed_runeword,
        "instance": instance,
    }


def rune_icon(key: str) -> str:
    return RUNES.get(key, {}).get("icon", "◻️")


def socket_line(instance) -> str:
    """Строка гнёзд для карточки предмета: «🔥 Руна Огня · пусто»."""
    parts = []
    for slot in range(1, SOCKETS + 1):
        key = getattr(instance, f"socket_{slot}", None)
        if key and key in RUNES:
            parts.append(f"{RUNES[key]['icon']} {RUNES[key]['name']}")
        else:
            parts.append("◻️ пусто")
    word = getattr(instance, "runeword", None)
    tail = f" · <b>{word}</b>" if word else ""
    return " · ".join(parts) + tail


class _DictInstance:
    """Обёртка над записью реестра `engine/items.py` под API insert_rune.

    Экземпляры браузерного стека — обычные словари, а `insert_rune`
    ожидает объект с атрибутами. Обёртка пишет изменения обратно в dict,
    чтобы не заводить вторую копию логики рун.
    """

    _FIELDS = ("socket_1", "socket_2", "runeword",
               "bonus_damage", "bonus_defense", "bonus_hp", "bonus_luck")

    def __init__(self, data: dict):
        object.__setattr__(self, "_data", data)

    def __getattr__(self, name):
        if name in self._FIELDS:
            if name.startswith("bonus_"):
                stats = self._data.get("stats") or {}
                return stats.get(name.replace("bonus_", ""), 0)
            return self._data.get(name)
        raise AttributeError(name)

    def __setattr__(self, name, value):
        if name in self._FIELDS:
            if name.startswith("bonus_"):
                stats = self._data.setdefault("stats", {})
                stats[name.replace("bonus_", "")] = value
            else:
                self._data[name] = value
            return
        object.__setattr__(self, name, value)


def insert_into_instance(inst: dict, rune_key: str, slot: int = 1) -> dict:
    """Вставить руну в экземпляр браузерного стека (запись реестра)."""
    if not isinstance(inst, dict):
        return insert_rune(inst, rune_key, slot)
    wrapper = _DictInstance(inst)
    res = insert_rune(wrapper, rune_key, slot)
    if res.get("ok"):
        res["instance"] = inst
    return res

