files.engine/legends.py:
"""Зал Славы: первопроходцы сервера.

Тексты и правило «рекорд фиксируется один раз» — общие для обоих стеков.
Различается хранилище: сервер пишет строки в таблицу `ServerRecord`,
браузерный стек — список в `store.settings` (таблиц там нет).

Рекорд именной и неизменяемый: кто первым убил босса или дошёл до дна
подземелья, тот и остаётся в летописи навсегда — поэтому повторная
запись того же ключа отклоняется.
"""
import time

KEY = "legends"      # ключ списка в store.settings
MAX_RECORDS = 50     # летопись не растёт бесконечно
SHOWN = 8            # столько записей показываем на экране


def _records(store):
    lst = store.settings.get(KEY)
    if not isinstance(lst, list):
        lst = []
        store.settings[KEY] = lst
    return lst


def all_records(store) -> list:
    """Записи от новых к старым."""
    return list(reversed(_records(store)))


def has_record(store, record_key: str) -> bool:
    return any(r.get("key") == record_key for r in _records(store))


def record_first(store, record_key: str, title: str, p, detail: str = "") -> bool:
    """Зафиксировать первопроходство. False — рекорд уже занят."""
    if has_record(store, record_key):
        return False
    lst = _records(store)
    lst.append({
        "key": record_key,
        "title": title,
        "holder": getattr(p, "name", "?"),
        "holder_id": int(getattr(p, "tg_id", 0) or 0),
        "detail": detail,
        "ts": int(time.time()),
    })
    store.settings[KEY] = lst[-MAX_RECORDS:]
    store.save()
    return True


def stamp(ts) -> str:
    try:
        return time.strftime("%d.%m.%Y", time.localtime(int(ts)))
    except (ValueError, TypeError, OSError):
        return "—"


def hall_text(records: list) -> str:
    """Экран Зала Славы. Принимает список словарей (движок) либо строк БД.

    Имя героя и заголовок экранируются: экран выводится с parse_mode="HTML"
    и в боте, и в браузерной панели, а имя — ввод игрока. Без `escape`
    имя вида `<b href=…>` испортило бы разметку (и это же stored-XSS в
    панели). Обёртки <b> добавляем уже после экранирования.
    """
    from html import escape

    def _h(text):
        return escape(str(text or ""), quote=False)

    if not records:
        return (
            "🏆 <b>Глобальный Зал Славы (Server Legends)</b>\n\n"
            "Летопись мира пока пуста. Соверши великий подвиг, чтобы твоё "
            "имя навеки вошло в историю!"
        )
    lines = ["🏆 <b>Глобальный Зал Славы Теневых Земель</b>\n"]
    for r in records[:SHOWN]:
        if isinstance(r, dict):
            title, holder, when = _h(r.get("title", "?")), _h(r.get("holder", "?")), stamp(r.get("ts"))
        else:                                   # строка ServerRecord с сервера
            title = _h(r.title)
            holder = _h(r.holder_character_name)
            when = r.achieved_at.strftime("%d.%m.%Y") if r.achieved_at else "—"
        lines.append(f"⭐ <b>{title}</b>\n   Первопроходец: <b>{holder}</b> ({when})\n")
    return "\n".join(lines)

files.engine/guilds.py:
"""Гильдии и наставничество: союзы между героями.

Правила — **единственный источник правды** для обоих стеков: цена
основания, взносы, пороги наставничества и бонус ученика берутся отсюда
и серверными модулями тоже. Хранилище различается: сервер держит таблицы
`guilds`/`guild_members`, браузерный стек — записи в `store.settings`.
"""
import time

GUILDS_KEY = "guilds"

CREATE_COST = 2000       # основание гильдии — заметная трата, не спонтанная
START_TREASURY = 500     # часть взноса сразу ложится в казну
MENTOR_MIN_LEVEL = 8     # с этого уровня можно вести ученика
APPRENTICE_MAX_LEVEL = 5  # до этого уровня героя ещё считают новичком
MENTOR_EXP_BONUS_PCT = 25
HONOR_PER_PROGRESS = 25   # очки чести наставнику за успехи ученика


def _guilds(store) -> dict:
    data = store.settings.get(GUILDS_KEY)
    if not isinstance(data, dict):
        data = {}
        store.settings[GUILDS_KEY] = data
    return data


def all_guilds(store) -> list:
    return sorted(_guilds(store).values(),
                  key=lambda g: (-int(g.get("level", 1)), g.get("name", "")))


def guild_of(store, p):
    """Гильдия героя и его роль в ней, либо (None, "")."""
    mine = int(getattr(p, "tg_id", 0) or 0)
    for g in _guilds(store).values():
        for m in g.get("members", []):
            if int(m.get("id", 0)) == mine:
                return g, m.get("role", "member")
    return None, ""


def create(store, p, name: str) -> dict:
    """Основать гильдию. Деньги списывает вызывающий код."""
    name = (name or "").strip()
    if not name:
        return {"ok": False, "reason": "У гильдии должно быть имя."}
    if any(g.get("name") == name for g in _guilds(store).values()):
        return {"ok": False, "reason": "Гильдия с таким именем уже существует."}

    data = _guilds(store)
    gid = str(int(time.time() * 1000) % 10_000_000)
    data[gid] = {
        "id": gid,
        "name": name,
        "desc": f"Гильдия под предводительством {p.name}",
        "level": 1,
        "treasury": START_TREASURY,
        "leader": int(p.tg_id),
        "members": [{"id": int(p.tg_id), "name": p.name, "role": "leader"}],
    }
    store.settings[GUILDS_KEY] = data
    store.save()
    return {"ok": True, "guild": data[gid]}


def join(store, p, guild_id: str) -> dict:
    """Вступить в гильдию."""
    existing, _role = guild_of(store, p)
    if existing is not None:
        return {"ok": False, "reason": "Ты уже состоишь в гильдии."}
    g = _guilds(store).get(str(guild_id))
    if g is None:
        return {"ok": False, "reason": "Такой гильдии больше нет."}
    g.setdefault("members", []).append(
        {"id": int(p.tg_id), "name": p.name, "role": "member"})
    store.save()
    return {"ok": True, "guild": g}


def deposit(store, guild: dict, amount: int) -> int:
    """Внести взнос в казну. Деньги списывает вызывающий код."""
    guild["treasury"] = int(guild.get("treasury", 0)) + int(amount)
    store.save()
    return guild["treasury"]


# ── наставничество ──────────────────────────────────────────

def can_mentor(mentor, apprentice) -> tuple:
    """(можно ли, причина отказа) — правила те же, что в core/mentorship."""
    if int(getattr(mentor, "tg_id", 0)) == int(getattr(apprentice, "tg_id", 0)):
        return False, "Нельзя стать наставником самому себе."
    if (mentor.level or 1) < MENTOR_MIN_LEVEL:
        return False, (f"Стать наставником может лишь опытный воин "
                       f"({MENTOR_MIN_LEVEL}+ уровень).")
    if (apprentice.level or 1) > APPRENTICE_MAX_LEVEL:
        return False, (f"Учеником может стать только начинающий путник "
                       f"(1–{APPRENTICE_MAX_LEVEL} уровень).")
    if getattr(apprentice, "mentor_id", 0):
        return False, "У этого героя уже есть наставник."
    return True, ""


def bind_mentor(store, apprentice, mentor) -> dict:
    ok, reason = can_mentor(mentor, apprentice)
    if not ok:
        return {"ok": False, "reason": reason}
    apprentice.mentor_id = int(mentor.tg_id)
    store.save_player(apprentice)
    return {"ok": True, "mentor_name": mentor.name}


def mentor_bonuses(p) -> dict:
    has = bool(getattr(p, "mentor_id", 0))
    return {
        "has_mentor": has,
        "exp_bonus_pct": MENTOR_EXP_BONUS_PCT if has else 0,
        "honor_points": int(getattr(p, "honor_points", 0) or 0),
    }


def reward_mentor(store, apprentice) -> int:
    """Начислить наставнику очки чести за успехи ученика."""
    mentor_id = int(getattr(apprentice, "mentor_id", 0) or 0)
    if not mentor_id:
        return 0
    mentor = store.players.get(mentor_id)
    if mentor is None:
        return 0
    mentor.honor_points = int(getattr(mentor, "honor_points", 0) or 0) + HONOR_PER_PROGRESS
    store.save_player(mentor)
    return HONOR_PER_PROGRESS

files.engine/party.py:
"""Отряды: повод звать друзей.

До этого играть вместе было нельзя — взаимодействие исчерпывалось аукционом
и таблицей топа. Отряд до `MAX_SIZE` героев даёт общую добычу и делает
подземелья и боссов осмысленными.

Как устроено. Отряд — запись в настройках (общая для бота и панели):
`{"id", "leader", "members": [tg_id], "created"}`. Игрок состоит максимум
в одном. Приглашение кладётся приглашённому в `p.party_invite` и ждёт
ответа — навязать участие нельзя.

Делёж награды. Опыт и золото за победу получают все, кто **в той же
локации** (иначе можно было бы «возить» друга по миру, стоя в городе).
Каждому достаётся полная доля плюс бонус за игру вместе — но общий фонд
ограничен `MAX_TOTAL`, чтобы отряд не превращался в станок по печати денег.
"""
import time

from engine import currency
from engine.models import Reply

PARTIES = "parties"
MAX_SIZE = 3                 # больше — уже толпа, бой станет нечитаемым
TOGETHER_BONUS = 0.15        # +15% каждому за игру в отряде
MAX_TOTAL = 2.0              # суммарно отряд не получит больше, чем ×2


# ── хранилище ───────────────────────────────────────────────

def _all(store):
    lst = store.settings.get(PARTIES)
    if not isinstance(lst, list):
        lst = []
        store.settings[PARTIES] = lst
    return lst


def of(store, p):
    """Отряд игрока или None."""
    for party in _all(store):
        if int(p.tg_id) in [int(m) for m in party.get("members", [])]:
            return party
    return None


def members(store, p, same_loc=None):
    """Соратники игрока (без него самого). `same_loc` — только рядом."""
    party = of(store, p)
    if not party:
        return []
    out = []
    for tg_id in party.get("members", []):
        if int(tg_id) == int(p.tg_id):
            continue
        q = store.players.get(int(tg_id))
        if q is None or not q.created_char:
            continue
        if same_loc is not None and q.loc != same_loc:
            continue
        out.append(q)
    return out


def is_leader(store, p):
    party = of(store, p)
    return bool(party and int(party.get("leader", 0)) == int(p.tg_id))


# ── создание и приглашения ──────────────────────────────────

def create(store, p):
    if of(store, p):
        return Reply(alert="Ты уже в отряде.")
    party = {"id": int(time.time() * 1000) % 10_000_000,
             "leader": int(p.tg_id), "members": [int(p.tg_id)],
             "created": int(time.time())}
    _all(store).append(party)
    store.save()
    return card(store, p)


def invite(store, p, name_or_id):
    """Позвать героя по имени или Telegram ID."""
    party = of(store, p) or None
    if party is None:
        create(store, p)
        party = of(store, p)
    if int(party.get("leader", 0)) != int(p.tg_id):
        return Reply(alert="Звать в отряд может только предводитель.")
    if len(party.get("members", [])) >= MAX_SIZE:
        return Reply(alert=f"В отряде уже {MAX_SIZE} героя — больше некуда.")

    target = _find(store, name_or_id)
    if target is None:
        return Reply(alert="Такого героя нет.")
    if int(target.tg_id) == int(p.tg_id):
        return Reply(alert="Себя звать не нужно.")
    if of(store, target):
        return Reply(alert=f"{target.name} уже в отряде.")

    target.party_invite = int(party["id"])
    store.save_player(target)
    _tell(store, target.tg_id,
          f"🤝 <b>{p.name}</b> зовёт тебя в отряд!\n"
          f"Открой «🤝 Отряд» в меню, чтобы принять или отказаться.")
    return Reply(text=f"📨 Приглашение отправлено: <b>{target.name}</b>.",
                 keyboard=[[("🤝 Отряд", "party")], [("◀️ В мир", "world")]])


def _find(store, needle):
    needle = str(needle).strip().lower()
    if not needle:
        return None
    for q in store.players.values():
        if not q.created_char:
            continue
        if str(q.tg_id) == needle or q.name.lower() == needle:
            return q
    for q in store.players.values():          # частичное совпадение имени
        if q.created_char and needle in q.name.lower():
            return q
    return None


def accept(store, p):
    pid = int(getattr(p, "party_invite", 0) or 0)
    if not pid:
        return Reply(alert="Тебя никто не звал.")
    party = next((x for x in _all(store) if int(x["id"]) == pid), None)
    p.party_invite = 0
    if party is None:
        store.save_player(p)
        return Reply(alert="Этот отряд уже распался.")
    if len(party["members"]) >= MAX_SIZE:
        store.save_player(p)
        return Reply(alert="Отряд уже полон.")
    party["members"].append(int(p.tg_id))
    store.save_player(p)
    for q in members(store, p):
        _tell(store, q.tg_id, f"🤝 <b>{p.name}</b> присоединился к отряду!")
    return card(store, p)


def decline(store, p):
    p.party_invite = 0
    store.save_player(p)
    return Reply(text="Ты отклонил приглашение.",
                 keyboard=[[("◀️ В мир", "world")]])


def leave(store, p):
    party = of(store, p)
    if not party:
        return Reply(alert="Ты не в отряде.")
    party["members"] = [m for m in party["members"] if int(m) != int(p.tg_id)]
    leader_left = int(party.get("leader", 0)) == int(p.tg_id)
    if len(party["members"]) < 2:             # отряд из одного смысла не имеет
        for tg_id in party["members"]:
            _tell(store, tg_id, "🤝 Отряд распался.")
        _all(store)[:] = [x for x in _all(store) if x is not party]
    elif leader_left:
        party["leader"] = int(party["members"][0])
        _tell(store, party["leader"], "🤝 Теперь ты ведёшь отряд.")
    store.save()
    return Reply(text="🚪 Ты покинул отряд.",
                 keyboard=[[("🤝 Отряд", "party")], [("◀️ В мир", "world")]])


# ── общая награда ───────────────────────────────────────────

def share(store, p, gold, exp):
    """Раздать соратникам в той же локации их долю. Возвращает строки отчёта.

    Долю получает каждый, кто рядом; фонд ограничен MAX_TOTAL, поэтому
    большой отряд не выгоднее маленького сверх меры.
    """
    from engine import rules

    mates = members(store, p, same_loc=p.loc)
    if not mates:
        return []
    part = _fund(len(mates) + 1) / (len(mates) + 1)
    lines = []
    for q in mates:
        q_gold = max(1, int(gold * part))
        q_exp = max(1, int(exp * part))
        currency.earn(q, q_gold)
        levels = rules.add_exp(q, q_exp)
        store.save_player(q)
        _tell(store, q.tg_id,
              f"🤝 {p.name} бьётся рядом: +{q_gold} 🪙 +{q_exp} ⭐"
              + (f"\n🎖 Новый уровень: {q.level}!" if levels else ""))
        lines.append(f"🤝 {q.name}: +{q_gold} 🪙 +{q_exp} ⭐")
    return lines


def _fund(size):
    """Общий фонд награды на отряд из `size` героев, стоящих вместе."""
    if size < 2:
        return 1.0                        # один в поле — обычная награда
    return min(MAX_TOTAL, 1.0 + TOGETHER_BONUS * size)


def bonus(store, p):
    """Множитель награды самого игрока: его доля из общего фонда."""
    mates = members(store, p, same_loc=p.loc)
    if not mates:
        return 1.0                        # соратников рядом нет — как обычно
    size = len(mates) + 1
    return _fund(size) / size


# ── экраны ──────────────────────────────────────────────────

def card(store, p):
    """Экран отряда: состав, приглашение, выход."""
    pending = int(getattr(p, "party_invite", 0) or 0)
    if pending:
        party = next((x for x in _all(store) if int(x["id"]) == pending), None)
        who = store.players.get(int(party["leader"])) if party else None
        name = who.name if who else "Кто-то"
        return Reply(text=f"🤝 <b>Приглашение в отряд</b>\n\n<b>{name}</b> зовёт "
                          f"тебя в свой отряд.\n\n<i>Вместе добыча щедрее: "
                          f"+{int(TOGETHER_BONUS * 100)}% каждому, кто рядом.</i>",
                     keyboard=[[("✅ Принять", "pjoin"), ("❌ Отказаться", "pno")],
                               [("◀️ В мир", "world")]])

    party = of(store, p)
    if not party:
        return Reply(text=(
            "🤝 <b>Отряд</b>\n\nТы странствуешь в одиночку.\n\n"
            f"<i>В отряде до {MAX_SIZE} героев. Опыт и золото получают все, "
            f"кто в одной локации, и каждому идёт бонус "
            f"+{int(TOGETHER_BONUS * 100)}%.</i>\n\n"
            "Чтобы позвать: <code>/invite Имя</code> — или кнопкой ниже."),
            keyboard=[[("➕ Создать отряд", "pnew")], [("◀️ В мир", "world")]])

    lines = ["🤝 <b>Отряд</b>\n"]
    for tg_id in party["members"]:
        q = store.players.get(int(tg_id))
        if q is None:
            continue
        crown = "👑 " if int(party["leader"]) == int(tg_id) else "▫️ "
        near = "рядом" if q.loc == p.loc else "далеко"
        you = " (ты)" if int(tg_id) == int(p.tg_id) else ""
        lines.append(f"{crown}<b>{q.name}</b>{you} — ур. {q.level} · {near}")
    mates = members(store, p, same_loc=p.loc)
    if mates:
        lines.append(f"\n✨ Вместе: награда ×{_fund(len(mates) + 1):.2f} на отряд "
                     f"(каждому по {bonus(store, p) * 100:.0f}% от обычной)")
    else:
        lines.append("\n<i>Соратники в других краях — доли не будет, "
                     "пока не соберётесь вместе.</i>")

    rows = []
    if is_leader(store, p) and len(party["members"]) < MAX_SIZE:
        rows.append([("📨 Позвать: /invite Имя", "pnoop")])
    rows.append([("🚪 Покинуть отряд", "pleave")])
    rows.append([("◀️ В мир", "world")])
    return Reply(text="\n".join(lines), keyboard=rows)


def _tell(store, tg_id, text):
    """Весть соратнику через общую очередь исходящих."""
    from engine import adminops
    adminops.queue(store, int(tg_id), text)

files.engine/respawn.py:
"""Восстановление мира: твари и сундуки возвращаются со временем.

Без этого мир одноразовый: убитая тварь исчезала навсегда, вскрытый сундук
не появлялся снова, и через вечер игры карта пустела насовсем.

Как устроено. Убийство не стирает тварь молча, а ставит на клетку метку
`mob_at` — время возвращения. `tick()` вызывается на шаге игрока (там же,
где `cataclysm.auto`), поэтому фоновые задачи не нужны: мир оживает ровно
тогда, когда в него кто-то смотрит.

Сундук возвращается не на своё место, а на случайную клетку локации: иначе
игроки заучили бы точки и ходили по кругу.
"""
import random
import time

from engine import data
from engine import world as W

# Сколько ждать возвращения, в минутах, по типу локации.
MOB_DELAY = {"safe": 0, "dangerous": 15, "dungeon": 30, "boss": 45}
CHEST_DELAY = {"safe": 0, "dangerous": 25, "dungeon": 40, "boss": 60}

SETTING_MOB = "respawn_mob_min"      # переопределение из панели
SETTING_CHEST = "respawn_chest_min"
SETTING_ON = "respawn_enabled"


def enabled(store):
    return bool(store.settings.get(SETTING_ON, True))


def _loc_type(loc):
    return data.LOCATIONS[loc][2] if 0 <= loc < len(data.LOCATIONS) else "dangerous"


def _minutes(store, kind, loc):
    """Задержка для локации: настройка панели или значение по типу."""
    table = MOB_DELAY if kind == "mob" else CHEST_DELAY
    key = SETTING_MOB if kind == "mob" else SETTING_CHEST
    override = (store.settings.get(key) or {}).get(_loc_type(loc))
    if override is None:
        return table.get(_loc_type(loc), 15)
    try:
        return max(0, float(override))
    except (TypeError, ValueError):
        return table.get(_loc_type(loc), 15)


# ── постановка в очередь ────────────────────────────────────

def schedule_mob(store, cell):
    """Тварь убита: наметить возвращение. В безопасных землях — никогда."""
    cell.mob = -1
    delay = _minutes(store, "mob", cell.loc)
    cell.mob_at = (time.time() + delay * 60) if delay > 0 else 0.0


def schedule_chest(store, cell):
    """Сундук вскрыт: наметить появление нового где-то в этой локации."""
    cell.chest = False
    delay = _minutes(store, "chest", cell.loc)
    cell.chest_at = (time.time() + delay * 60) if delay > 0 else 0.0


# ── возвращение ─────────────────────────────────────────────

def tick(store, rng=None):
    """Вернуть всё, чей срок вышел. Возвращает (тварей, сундуков).

    Клетки под игроками пропускаем: тварь не должна возникать прямо под
    ногами, а сундук — появляться в занятой клетке.
    """
    if not enabled(store):
        return 0, 0
    rng = rng or random
    now = time.time()
    busy = {f"{p.loc}:{p.x}:{p.y}" for p in store.players.values()}
    mobs = chests = 0

    for c in store.world.values():
        if c.mob_at and now >= c.mob_at:
            if c.key in busy or not c.passable or c.mob >= 0 or c.npc >= 0:
                c.mob_at = now + 60          # занято — заглянем через минуту
                continue
            c.mob = _pick_mob(c.loc, rng)
            c.mob_at = 0.0
            mobs += 1

    # Сундуки: метка висит на вскрытой клетке, а сокровище кладём в другую.
    for c in list(store.world.values()):
        if not c.chest_at or now < c.chest_at:
            continue
        c.chest_at = 0.0
        spot = _free_spot(store, c.loc, busy, rng)
        if spot is not None:
            spot.chest = True
            chests += 1
    if mobs or chests:
        store.save()
    return mobs, chests


def _pick_mob(loc, rng):
    """Тварь под стать локации: свои по прописке, иначе по её уровню."""
    own = [i for i, m in enumerate(data.MOBS) if m[8] == loc]
    if own:
        return rng.choice(own)
    lvl = data.LOCATIONS[loc][3] if loc < len(data.LOCATIONS) else 1
    fit = [i for i, m in enumerate(data.MOBS) if m[2] <= max(1, lvl) + 2]
    return rng.choice(fit or range(len(data.MOBS)))


def _free_spot(store, loc, busy, rng):
    """Случайная свободная клетка локации под новый сундук."""
    free = [c for c in store.world.values()
            if c.loc == loc and c.passable and not c.link and not c.chest
            and c.mob < 0 and c.npc < 0 and c.key not in busy
            and (c.x, c.y) != W.SPAWN]
    return rng.choice(free) if free else None


# ── сводка для панели ───────────────────────────────────────

def pending(store, loc=None):
    """Что сейчас в очереди на возвращение: [(клетка, вид, секунд)]."""
    now = time.time()
    out = []
    for c in store.world.values():
        if loc is not None and c.loc != int(loc):
            continue
        if c.mob_at:
            out.append((c, "mob", max(0, int(c.mob_at - now))))
        if c.chest_at:
            out.append((c, "chest", max(0, int(c.chest_at - now))))
    return sorted(out, key=lambda r: r[2])


def delays(store):
    """Текущие задержки по типам локаций — для формы настроек."""
    out = {}
    for kind, table in (("mob", MOB_DELAY), ("chest", CHEST_DELAY)):
        out[kind] = {t: _minutes(store, kind, _first_loc_of(t))
                     for t in table}
    return out


def _first_loc_of(loc_type):
    """Индекс любой локации нужного типа — чтобы прочитать её задержку."""
    for i, l in enumerate(data.LOCATIONS):
        if l[2] == loc_type:
            return i
    return 0


def set_delays(store, kind, values):
    """Сохранить задержки по типам локаций (минуты)."""
    key = SETTING_MOB if kind == "mob" else SETTING_CHEST
    saved = store.settings.setdefault(key, {})
    for loc_type, raw in values.items():
        try:
            saved[loc_type] = max(0, float(raw))
        except (TypeError, ValueError):
            continue
    store.save()
    return saved

files.engine/quests.py:
"""Задания: цель для игрока и повод вернуться завтра.

Три вида, и все проверяются по тому, что в игре уже считается:
  hunt    — убить тварей вида (счётчик ведём при победе в бою);
  reach   — дойти до локации (сверяем с `p.visited`, туман войны уже есть);
  deliver — принести предмет заказчику (смотрим в сумке).

Состояние живёт в `p.quests`: {id задания: {"n": прогресс, "done": сдано}}.
Ежедневные сбрасываются раз в сутки по `p.quest_day`.
"""
import time

from engine import currency, data, factions, items, rules
from engine.models import Reply

HUNT, REACH, DELIVER = "hunt", "reach", "deliver"
DAILY_LIMIT = 2                 # сколько ежедневных доступно за раз


def _row(qid):
    for q in data.QUESTS:
        if q[0] == int(qid):
            return q
    return None


def fields(q):
    """Кортеж задания -> словарь, чтобы не помнить порядок полей."""
    return dict(id=q[0], name=q[1], text=q[2], npc=q[3], kind=q[4],
                target=q[5], need=q[6], gold=q[7], exp=q[8], item=q[9],
                level=q[10], daily=q[11])


def state(p):
    st = getattr(p, "quests", None)
    if not isinstance(st, dict):
        st = {}
        p.quests = st
    return st


# ── ежедневный сброс ────────────────────────────────────────

def _today():
    return time.strftime("%Y-%m-%d")


def refresh_daily(p):
    """Раз в сутки снимает отметки с ежедневных заданий. True, если сбросили."""
    if getattr(p, "quest_day", "") == _today():
        return False
    st = state(p)
    for q in data.QUESTS:
        if q[11]:
            st.pop(str(q[0]), None)
    p.quest_day = _today()
    return True


# ── доступность ─────────────────────────────────────────────

def taken(p, qid):
    return str(qid) in state(p)


def done(p, qid):
    return bool(state(p).get(str(qid), {}).get("done"))


def available(p, npc_index=None):
    """Задания, которые игрок может взять у этого NPC (или вообще)."""
    refresh_daily(p)
    out = []
    dailies = 0
    for q in data.QUESTS:
        f = fields(q)
        if npc_index is not None and f["npc"] != int(npc_index):
            continue
        if p.level < f["level"] or taken(p, f["id"]):
            continue
        if f["daily"]:
            dailies += 1
            if dailies > DAILY_LIMIT:
                continue
        out.append(q)
    return out


def active(p):
    """Взятые и ещё не сданные."""
    refresh_daily(p)
    st = state(p)
    return [q for q in data.QUESTS
            if str(q[0]) in st and not st[str(q[0])].get("done")]


def take(p, qid):
    q = _row(qid)
    if q is None:
        return Reply(alert="Такого задания нет.")
    f = fields(q)
    if p.level < f["level"]:
        return Reply(alert=f"Нужен {f['level']} уровень.")
    if taken(p, qid):
        return Reply(alert="Это задание уже у тебя.")
    state(p)[str(qid)] = {"n": 0, "done": False}
    if f["kind"] == REACH and _reached(p, f["target"]):
        state(p)[str(qid)]["n"] = f["need"]      # уже бывал там
    return Reply(text=f"📜 <b>Задание принято</b>\n\n<b>{f['name']}</b>\n"
                      f"<i>{f['text']}</i>\n\n{goal_line(p, q)}",
                 keyboard=[[("📜 Мои задания", "quests")], [("◀️ В мир", "world")]])


def abandon(p, qid):
    if not taken(p, qid):
        return Reply(alert="Ты за это не брался.")
    state(p).pop(str(qid), None)
    return Reply(text="🚮 Задание отброшено.", keyboard=[[("📜 Задания", "quests")]])


# ── прогресс ────────────────────────────────────────────────

def _reached(p, loc):
    return any(k.startswith(f"{int(loc)}:") for k in (getattr(p, "visited", []) or []))


def on_kill(p, mob_index):
    """Победа над тварью двигает охотничьи задания. Возвращает готовые."""
    ready = []
    for q in active(p):
        f = fields(q)
        if f["kind"] != HUNT:
            continue
        if f["target"] not in (-1, int(mob_index)):
            continue
        rec = state(p)[str(f["id"])]
        rec["n"] = min(f["need"], rec.get("n", 0) + 1)
        if rec["n"] >= f["need"]:
            ready.append(q)
    return ready


def on_enter(p, loc):
    """Приход в локацию закрывает разведку."""
    ready = []
    for q in active(p):
        f = fields(q)
        if f["kind"] == REACH and int(f["target"]) == int(loc):
            rec = state(p)[str(f["id"])]
            rec["n"] = f["need"]
            ready.append(q)
    return ready


def progress(p, q):
    """Сколько сделано из нужного."""
    f = fields(q)
    if f["kind"] == DELIVER:
        have = sum(1 for i in p.inventory if int(i) == int(f["target"]))
        return min(have, f["need"]), f["need"]
    rec = state(p).get(str(f["id"]), {})
    return min(rec.get("n", 0), f["need"]), f["need"]


def complete(p, q):
    n, need = progress(p, q)
    return n >= need


def goal_line(p, q):
    """Человеческая строка цели с прогрессом."""
    f = fields(q)
    n, need = progress(p, q)
    if f["kind"] == HUNT:
        who = data.MOBS[f["target"]][0] if f["target"] >= 0 else "любые твари"
        what = f"⚔️ {who}: {n}/{need}"
    elif f["kind"] == REACH:
        where = (data.LOCATIONS[f["target"]][0]
                 if f["target"] < len(data.LOCATIONS) else "?")
        what = f"🧭 Дойти: {where} — {'да' if n >= need else 'ещё нет'}"
    else:
        it = rules.item(f["target"])
        what = f"🎒 {it['icon']} {it['name']}: {n}/{need}"
    prize = f"🪙 {f['gold']} · ⭐ {f['exp']}"
    if f["item"] >= 0:
        it = rules.item(f["item"])
        prize += f" · {it['icon']} {it['name']}"
    return f"{what}\n🎁 Награда: {prize}"


# ── сдача ───────────────────────────────────────────────────

def hand_in(store, p, qid):
    q = _row(qid)
    if q is None or not taken(p, qid):
        return Reply(alert="Это задание не у тебя.")
    if done(p, qid):
        return Reply(alert="Уже сдано.")
    f = fields(q)
    if not complete(p, q):
        return Reply(alert="Задание ещё не выполнено.")

    if f["kind"] == DELIVER:                 # предмет уходит заказчику
        from engine import slots
        for _ in range(f["need"]):
            slots.take_first_unequipped(p, int(f["target"]))

    currency.earn(p, f["gold"])
    levels = rules.add_exp(p, f["exp"])
    lines = [f"✅ <b>{f['name']}</b> — выполнено!",
             f"🪙 +{f['gold']}   ⭐ +{f['exp']}"]
    if f["item"] >= 0:
        p.inventory.append(int(f["item"]))
        inst = items.create(store, int(f["item"]), source="quest",
                            owner=p.tg_id, luck=p.luck, detail=f["name"])
        if inst is not None:
            lines.append(f"📜 Награда: {inst['icon']} <b>{items.title(inst)}</b>")
        else:
            it = rules.item(f["item"])
            lines.append(f"📜 Награда: {it['icon']} {it['name']}")
    lines.extend(factions.award(store, p, "quest_done"))
    if levels:
        lines.append(f"\n🎖 <b>Новый уровень: {p.level}!</b>")

    if f["daily"]:
        state(p).pop(str(qid), None)         # завтра можно взять снова
    else:
        state(p)[str(qid)]["done"] = True
    store.save_player(p)
    return Reply(text="\n".join(lines),
                 keyboard=[[("📜 Задания", "quests")], [("◀️ В мир", "world")]])


# ── экраны ──────────────────────────────────────────────────

def journal(p):
    """Дневник: что взято и что можно сдать."""
    refresh_daily(p)
    live = active(p)
    rows, lines = [], []
    for q in live:
        f = fields(q)
        mark = "✅" if complete(p, q) else "▫️"
        daily = " 🔄" if f["daily"] else ""
        lines.append(f"{mark} <b>{f['name']}</b>{daily}\n{goal_line(p, q)}")
        if complete(p, q):
            rows.append([(f"✅ Сдать: {f['name'][:18]}", f"qdone:{f['id']}")])
        else:
            rows.append([(f"🚮 Бросить: {f['name'][:16]}", f"qdrop:{f['id']}")])
    if not live:
        lines.append("<i>Заданий нет. Загляни к жителям Погоста — у них всегда "
                     "найдётся работа.</i>")
    rows.append([("◀️ В мир", "world"), ("◀️ Меню", "menu")])
    return Reply(text="📜 <b>Дневник заданий</b>\n\n" + "\n\n".join(lines),
                 keyboard=rows)


def offer_rows(p, npc_index):
    """Кнопки «взять задание» для диалога с NPC."""
    rows = []
    for q in available(p, npc_index):
        f = fields(q)
        tag = "🔄 " if f["daily"] else "📜 "
        rows.append([(f"{tag}{f['name']}", f"qtake:{f['id']}")])
    for q in active(p):
        f = fields(q)
        if f["npc"] == int(npc_index) and complete(p, q):
            rows.append([(f"✅ Сдать: {f['name'][:18]}", f"qdone:{f['id']}")])
    return rows


def card(p, qid):
    """Карточка задания перед принятием."""
    q = _row(qid)
    if q is None:
        return Reply(alert="Задание не найдено.")
    f = fields(q)
    return Reply(text=f"📜 <b>{f['name']}</b>\n\n<i>{f['text']}</i>\n\n{goal_line(p, q)}",
                 keyboard=[[("✔️ Взять", f"qtake:{f['id']}")],
                           [("◀️ Назад", "world")]])

