files.engine/permissions.py:
"""Права доступа к админке: отдельные функции + ранги, как в кланах MMO.

Ранг — это просто пресет набора «капабилити». Любой ранг можно донастроить
галочками: выдать гейм-мастеру рассылку, забрать у модератора удаление и т.д.
"""
import random
import string

# (ключ, подпись, группа)
CAPS = [
    ("view_dash",    "📊 Видеть сводку",            "Просмотр"),
    ("view_players", "👥 Видеть игроков",           "Просмотр"),
    ("view_world",   "🗺 Видеть карту мира",        "Просмотр"),
    ("view_content", "📦 Видеть контент",           "Просмотр"),
    ("edit_players", "✏️ Править статы игроков",    "Игроки"),
    ("heal_players", "💊 Лечить игроков",           "Игроки"),
    ("give_items",   "🎁 Выдавать предметы",        "Игроки"),
    ("del_players",  "🗑 Удалять игроков",          "Игроки"),
    ("edit_world",   "🧱 Править клетки мира",      "Мир"),
    ("regen_world",  "🎲 Пересоздавать мир",        "Мир"),
    ("dungeons",     "🕳 Порталы и подземелья",     "Мир"),
    ("cataclysms",   "🌋 Насылать катаклизмы",      "Мир"),
    ("edit_content", "📝 Править контент игры",     "Контент"),
    ("bot_control",  "🤖 Запуск/остановка бота",    "Система"),
    ("broadcast",    "📣 Рассылка игрокам",         "Система"),
    ("settings",     "⚙️ Настройки, экспорт, сброс", "Система"),
    ("grant_admin",  "👑 Выдавать доступ другим",   "Система"),
]

CAP_KEYS = [k for k, _, _ in CAPS]
CAP_LABELS = {k: lbl for k, lbl, _ in CAPS}
CAP_GROUPS = []
for _k, _lbl, _g in CAPS:
    if _g not in CAP_GROUPS:
        CAP_GROUPS.append(_g)

# Ранги: (подпись, пресет капабилити)
RANKS = {
    "viewer": ("👁 Наблюдатель", [
        "view_dash", "view_players", "view_world", "view_content"]),
    "moderator": ("🛡 Модератор", [
        "view_dash", "view_players", "view_world", "view_content",
        "heal_players", "give_items"]),
    "gamemaster": ("🎲 Гейм-мастер", [
        "view_dash", "view_players", "view_world", "view_content",
        "edit_players", "heal_players", "give_items",
        "edit_world", "dungeons", "cataclysms", "edit_content", "broadcast"]),
    "admin": ("👑 Администратор", list(CAP_KEYS)),
}

RANK_KEYS = ["viewer", "moderator", "gamemaster", "admin"]


def rank_title(rank):
    return RANKS.get(rank, RANKS["viewer"])[0]


def rank_caps(rank):
    """Пресет капабилити ранга."""
    return list(RANKS.get(rank, RANKS["viewer"])[1])


def caps_of(player):
    """Итоговый набор прав игрока: индивидуальный список либо пресет ранга."""
    if not getattr(player, "is_web_admin", False):
        return set()
    custom = getattr(player, "web_admin_caps", None)
    if custom:
        return {c for c in custom if c in CAP_LABELS}
    return set(rank_caps(getattr(player, "web_admin_role", "viewer")))


def can(player, cap):
    return cap in caps_of(player)


def can_any(player, *caps):
    mine = caps_of(player)
    return any(c in mine for c in caps)


def new_password(length=8):
    """Читаемый пароль без похожих символов (0/O, 1/l)."""
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789"
    try:
        import secrets
        pick = secrets.choice
    except Exception:                              # pragma: no cover
        pick = random.choice
    return "".join(pick(alphabet) for _ in range(length))


def summary(player):
    """Короткая сводка прав для показа игроку в боте."""
    mine = caps_of(player)
    if not mine:
        return "—"
    return "\n".join(f"• {CAP_LABELS[k]}" for k in CAP_KEYS if k in mine)


def slug(text):
    """Безопасный ключ из произвольной строки (для id элементов формы)."""
    return "".join(ch if ch in string.ascii_letters + string.digits else "_"
                   for ch in str(text))


def normalize_url(raw):
    """https://host без хвостового слэша. Пустая строка, если ничего не ввели."""
    url = (raw or "").strip()
    if not url:
        return ""
    if not url.startswith(("http://", "https://")):
        url = "https://" + url
    return url.rstrip("/")


def login_url(base, tg_id):
    """Ссылка входа в панель для инлайн-кнопки бота."""
    base = normalize_url(base)
    return f"{base}/admin-login?uid={tg_id}" if base else ""

files.engine/mapview.py:
"""Карта локации для игрока: плитки-эмодзи и туман войны.

Никаких «#», «.», «@» — карта собирается из цветных квадратов, а неисследованные
клетки скрыты туманом. Игрок открывает мир, проходя по нему.
"""
from engine import data
from engine import world as W
from engine.models import Reply

TILE = {
    "grass": "🟩",
    "forest": "🌲",
    "road": "🟧",
    "water": "🟦",
    "wall": "⬛",
    "village": "🏠",
    "cave": "🟪",
}

FOG = "⬜"        # не исследовано
PLAYER = "🔴"     # ты
OTHER = "🔵"      # другой герой
DOOR = "🚪"       # переход в соседнюю локацию
PORTAL = "🌀"     # открытый портал в подземелье
CHEST = "📦"
MOB = "👾"
NPC = "💬"
GRAVE = "🪦"      # чьё-то надгробие с золотом
STAIRS = "🪜"
MARK = "❇️"       # неизученная достопримечательность


def ckey(loc, x, y, floor=0):
    return f"{loc}:{x}:{y}" if not floor else f"{loc}:{floor}:{x}:{y}"


def mark_visited(p, loc=None, x=None, y=None):
    """Отмечает клетку как исследованную вместе с соседями (радиус обзора 1)."""
    loc = p.loc if loc is None else loc
    x = p.x if x is None else x
    y = p.y if y is None else y
    floor = getattr(p, "floor", 0)
    seen = set(getattr(p, "visited", []) or [])
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx, ny = x + dx, y + dy
            if 0 <= nx < W.SIZE and 0 <= ny < W.SIZE:
                seen.add(ckey(loc, nx, ny, floor))
    p.visited = sorted(seen)


def is_visited(p, loc, x, y, floor=0):
    return ckey(loc, x, y, floor) in set(getattr(p, "visited", []) or [])


def others_here(store, p, loc=None, x=None, y=None):
    """Другие герои в клетке. Пустой список, если хранилища нет."""
    if store is None:
        return []
    loc = p.loc if loc is None else loc
    return [q for q in store.players.values()
            if q.created_char and q.tg_id != p.tg_id and q.loc == loc
            and (x is None or (q.x == x and q.y == y))]


def other_keys(store, p):
    """{ключ клетки: [герои]} — где сейчас стоят остальные в этой локации."""
    out = {}
    for q in others_here(store, p):
        out.setdefault(ckey(q.loc, q.x, q.y, getattr(q, "floor", 0)), []).append(q)
    return out


def _mark_keys(store, p):
    """Неизученные достопримечательности: изученные больше не мигают."""
    if store is None:
        return set()
    from engine import landmarks
    seen = set(getattr(p, "landmarks", None) or [])
    return landmarks.keys(store) - seen


def _grave_keys(store):
    if store is None:
        return set()
    from engine import death
    return death.keys(store)


def portal_keys(store):
    """Ключи клеток, где сейчас открыты порталы подземелий."""
    out = {}
    for tpl in store.settings.get("dungeon_templates", []) or []:
        key = tpl.get("portal_cell")
        if key:
            out[key] = tpl
    return out


def glyph(cell, portals=(), graves=(), marks=()):
    """Символ клетки на карте (без учёта тумана и позиции игрока)."""
    if cell is None or not cell.passable:
        return TILE["wall"]
    if cell.key in graves:
        return GRAVE
    if cell.key in marks:
        return MARK
    if cell.key in portals:
        return PORTAL
    if getattr(cell, "floor_links", ()):
        return STAIRS
    if cell.link:
        return DOOR
    if cell.mob >= 0:
        return MOB
    if cell.npc >= 0:
        return NPC
    if cell.chest:
        return CHEST
    return TILE.get(cell.tile, TILE["grass"])


def grid(p, cells, portals=(), others=None, graves=(), marks=()):
    """Список строк карты текущей локации игрока.

    `others` — {ключ: [герои]}: соседи видны синей точкой, но только в уже
    изученных клетках, иначе карта выдавала бы содержимое тумана.
    """
    others = others or {}
    rows = []
    for x in range(W.SIZE):
        row = ""
        for y in range(W.SIZE):
            if (x, y) == (p.x, p.y):
                row += PLAYER
                continue
            if not is_visited(p, p.loc, x, y, getattr(p, "floor", 0)):
                row += FOG
                continue
            if others.get(ckey(p.loc, x, y)):
                row += OTHER
                continue
            row += glyph(cells.get(ckey(p.loc, x, y, getattr(p, "floor", 0))), portals, graves, marks)
        rows.append(row)
    return rows


def render(p, cells, store=None):
    """Reply с картой локации: туман войны, легенда, прогресс исследования."""
    portals = portal_keys(store) if store is not None else {}
    others = other_keys(store, p) if store is not None else {}
    graves = _grave_keys(store)
    marks = _mark_keys(store, p)
    rows = grid(p, cells, portals, others, graves, marks)

    floor = getattr(p, "floor", 0)
    total = sum(1 for c in cells.values() if c.loc == p.loc and c.floor == floor)
    prefix = f"{p.loc}:" if floor == 0 else f"{p.loc}:{floor}:"
    seen = sum(1 for k in (getattr(p, "visited", []) or []) if k.startswith(prefix))
    pct = int(seen / total * 100) if total else 0

    loc = data.LOCATIONS[p.loc] if p.loc < len(data.LOCATIONS) else ("Неизвестность",)
    legend = (f"{PLAYER} ты · {OTHER} герой · {FOG} не изучено · "
              f"{TILE['wall']} стена · {DOOR} переход · {STAIRS} лестница\n"
              f"{PORTAL} портал · {MOB} враг · {NPC} житель · {CHEST} сундук · "
              f"{GRAVE} могила · {MARK} диковина")

    nearby = len(others)
    company = f" · {OTHER} рядом героев: {nearby}" if nearby else ""
    found_marks = ""
    if store is not None:
        from engine import landmarks
        fnd, allm = landmarks.total(store, p)
        if allm:
            found_marks = f" · {MARK} {fnd}/{allm}"
    text = (f"🗺 <b>{loc[0]}</b>\n"
            f"📍 Ты на [{p.x},{p.y}] · изучено {seen}/{total} ({pct}%)"
            f"{company}{found_marks}\n\n"
            + "\n".join(rows) + "\n\n" + legend)

    return Reply(text=text, keyboard=[
        [("🔄 Обновить", "map"), ("🧭 Назад в мир", "world")],
        [("◀️ Меню", "menu")],
    ])

files.engine/audit.py:
"""Единый журнал действий администраторов.

И бот, и веб-панель пишут сюда через один и тот же Store, поэтому запись,
сделанная кнопкой в Telegram, тут же видна во вкладке «Действия админов»
и наоборот. Никаких браузерных зависимостей — только stdlib.
"""
import time

KEY = "audit"
LIMIT = 400                       # сколько последних записей храним

SOURCES = {"bot": "🤖 Бот", "panel": "🖥 Панель"}
OWNER = "Владелец"


def _log(store):
    lst = store.settings.get(KEY)
    if not isinstance(lst, list):
        lst = []
        store.settings[KEY] = lst
    return lst


def record(store, actor, action, target="", detail="", source="panel"):
    """actor: Player | строка-имя | None (владелец панели без входа)."""
    who, name = 0, OWNER
    if actor is None:
        pass
    elif isinstance(actor, str):
        name = actor or OWNER
    else:
        who = int(getattr(actor, "tg_id", 0) or 0)
        name = getattr(actor, "name", "") or f"#{who}"

    entry = {
        "ts": int(time.time()),
        "who": who,
        "name": name,
        "act": str(action),
        "target": str(target),
        "detail": str(detail),
        "src": source if source in SOURCES else "panel",
    }
    lst = _log(store)
    lst.append(entry)
    if len(lst) > LIMIT:
        del lst[:-LIMIT]
    store.settings[KEY] = lst
    try:
        store.save()
    except Exception:                                     # pragma: no cover
        pass
    return entry


def entries(store, source="", who=0, search="", date_from="", date_to="", limit=LIMIT):
    """Записи от новых к старым, с необязательными фильтрами."""
    out = []
    q = (search or "").lower()
    df = _parse_ts(date_from, start=True) if date_from else None
    dt = _parse_ts(date_to, start=False) if date_to else None
    for e in _log(store):
        if source and e.get("src") != source:
            continue
        if who and int(e.get("who") or 0) != int(who):
            continue
        if df and int(e.get("ts", 0)) < df:
            continue
        if dt and int(e.get("ts", 0)) > dt:
            continue
        if q and q not in (e.get("act", "") + " " + e.get("target", "") + " " + e.get("detail", "")).lower():
            continue
        out.append(e)
    out.reverse()
    return out[:limit]


def _parse_ts(value, start=True):
    """Парсит YYYY-MM-DD или DD.MM.YYYY в timestamp."""
    import time
    value = (value or "").strip()
    for fmt in ("%Y-%m-%d", "%d.%m.%Y"):
        try:
            t = time.strptime(value, fmt)
            if start:
                return int(time.mktime((t.tm_year, t.tm_mon, t.tm_mday, 0, 0, 0, 0, 0, -1)))
            return int(time.mktime((t.tm_year, t.tm_mon, t.tm_mday, 23, 59, 59, 0, 0, -1)))
        except ValueError:
            continue
    return None


def count(store, source=""):
    return len(entries(store, source=source))


def clear(store):
    store.settings[KEY] = []
    store.save()


def stamp(entry, fmt="%d.%m %H:%M"):
    try:
        return time.strftime(fmt, time.localtime(int(entry.get("ts", 0))))
    except Exception:                                     # pragma: no cover
        return "—"


def line(entry):
    """Одна запись журнала строкой для сообщения в боте."""
    src = SOURCES.get(entry.get("src"), "")
    target = f" → <code>{entry.get('target')}</code>" if entry.get("target") else ""
    detail = f"\n   <i>{entry.get('detail')}</i>" if entry.get("detail") else ""
    return (f"{stamp(entry)} · {src}\n"
            f"   <b>{entry.get('name')}</b>: {entry.get('act')}{target}{detail}")

files.engine/adminops.py:
"""Операции администратора — единственная реализация для бота и панели.

Любое админ-действие проходит через эти функции: они проверяют право,
меняют состояние, пишут запись в журнал (engine.audit) и при необходимости
кладут сообщение игроку в исходящую очередь (outbox), которую разбирает
транспорт бота. Поэтому кнопка в Telegram и кнопка в панели делают ровно
одно и то же и одинаково видны во вкладке «Действия админов».
"""
from engine import audit, data, permissions, rules

OUTBOX = "outbox"
MAX_OUTBOX = 200


# ── исходящие сообщения игрокам ─────────────────────────────

def queue(store, chat_id, text):
    """Ставит сообщение в очередь. Отправит тот, кто держит соединение."""
    box = store.settings.get(OUTBOX)
    if not isinstance(box, list):
        box = []
    box.append({"to": int(chat_id), "text": text})
    store.settings[OUTBOX] = box[-MAX_OUTBOX:]
    store.save()


def queue_all(store, text, skip=0):
    for tg_id in list(store.players):
        if skip and int(tg_id) == int(skip):
            continue
        queue(store, tg_id, text)


def drain(store):
    """Забирает и очищает очередь: [(chat_id, text), ...]."""
    box = store.settings.get(OUTBOX) or []
    store.settings[OUTBOX] = []
    if box:
        store.save()
    return [(int(m["to"]), m["text"]) for m in box if m.get("to")]


# ── общая обвязка ───────────────────────────────────────────

class Denied(Exception):
    """Не хватает права на действие."""


def require(actor, cap):
    """actor=None — владелец панели (полный доступ)."""
    if actor is None:
        return True
    if permissions.can(actor, cap):
        return True
    raise Denied(f"Нужно право «{permissions.CAP_LABELS.get(cap, cap)}»")


def allowed(actor, cap):
    try:
        return require(actor, cap)
    except Denied:
        return False


def _done(store, actor, source, action, target="", detail=""):
    audit.record(store, actor, action, target, detail, source)
    return True, detail or action


def _target(store, tg_id):
    p = store.players.get(int(tg_id))
    if not p:
        raise Denied("Игрок не найден")
    return p


def _who(p):
    return f"{p.name} #{p.tg_id}"


# ── игроки ──────────────────────────────────────────────────

def heal(store, actor, tg_id, source="panel"):
    require(actor, "heal_players")
    p = _target(store, tg_id)
    s = rules.stats(p)
    p.hp, p.mp = s["max_hp"], s["max_mp"]
    store.save_player(p)
    queue(store, p.tg_id, "💊 Администратор полностью восстановил твои силы.")
    return _done(store, actor, source, "Исцелил игрока", _who(p),
                 f"HP/MP → {s['max_hp']}/{s['max_mp']}")


def give_item(store, actor, tg_id, item_idx, source="panel"):
    require(actor, "give_items")
    p = _target(store, tg_id)
    idx = int(item_idx)
    if not 0 <= idx < len(data.ITEMS):
        raise Denied("Нет такого предмета")
    p.inventory.append(idx)
    store.save_player(p)
    it = rules.item(idx)
    queue(store, p.tg_id, f"🎁 Тебе выдан предмет: {it['icon']} <b>{it['name']}</b>")
    return _done(store, actor, source, "Выдал предмет", _who(p),
                 f"{it['icon']} {it['name']}")


def add_gold(store, actor, tg_id, amount, source="panel"):
    require(actor, "edit_players")
    p = _target(store, tg_id)
    amount = int(amount)
    # Админ оперирует бронзой — той же единицей, что и весь движок.
    from engine import currency
    if amount >= 0:
        currency.earn(p, amount)
    else:
        currency.spend(p, min(-amount, currency.total(p)))
    store.save_player(p)
    sign = "+" if amount >= 0 else ""
    queue(store, p.tg_id, f"🪙 Администратор изменил твоё золото: {sign}{amount}")
    return _done(store, actor, source, "Изменил золото", _who(p),
                 f"{sign}{amount} → {currency.fmt(p)}")


def add_level(store, actor, tg_id, delta, source="panel"):
    require(actor, "edit_players")
    p = _target(store, tg_id)
    delta = int(delta)
    old_level = p.level
    new_level = max(1, old_level + delta)
    actual_delta = new_level - old_level
    p.level = new_level
    if actual_delta != 0:
        from engine import hero
        gains = hero.growth(p.cls)
        for key, step in gains.items():
            setattr(p, key, max(0, getattr(p, key, 0) + int(step) * actual_delta))
        p.hp = p.max_hp
    store.save_player(p)
    sign = "+" if delta >= 0 else ""
    queue(store, p.tg_id, f"⭐ Твой уровень изменён администратором: {sign}{delta}")
    return _done(store, actor, source, "Изменил уровень", _who(p),
                 f"{sign}{delta} → ур. {p.level}")


def set_fields(store, actor, tg_id, fields, source="panel"):
    """Пакетная правка статов из формы панели."""
    require(actor, "edit_players")
    p = _target(store, tg_id)

    # Check if level changed
    level_val = fields.get("level")
    if level_val is not None:
        try:
            new_level = max(1, int(level_val))
            delta = new_level - p.level
            if delta != 0:
                from engine import hero
                gains = hero.growth(p.cls)
                for stat, step in gains.items():
                    form_val = fields.get(stat)
                    if form_val is not None:
                        try:
                            if int(form_val) == getattr(p, stat, 0):
                                fields[stat] = max(0, int(form_val) + int(step) * delta)
                        except (ValueError, TypeError):
                            pass
                    else:
                        setattr(p, stat, max(0, getattr(p, stat, 0) + int(step) * delta))
        except (ValueError, TypeError):
            pass

    # Карма — не свободное число: у неё жёсткий диапазон, за которым
    # ломаются пороги Благочестивого/Осквернителя (engine/karma.py).
    if "karma_score" in fields:
        try:
            from engine import karma
            fields["karma_score"] = max(
                karma.MIN_KARMA, min(karma.MAX_KARMA, int(fields["karma_score"])))
        except (ValueError, TypeError):
            fields.pop("karma_score")

    changed = []
    for k, v in fields.items():
        if not hasattr(p, k):
            continue
        old = getattr(p, k)
        if str(old) == str(v):
            continue
        setattr(p, k, v)
        changed.append(f"{k}: {old}→{v}")
    store.save_player(p)
    return _done(store, actor, source, "Правка статов", _who(p),
                 ", ".join(changed) if changed else "без изменений")


def delete_player(store, actor, tg_id, source="panel"):
    require(actor, "del_players")
    p = _target(store, tg_id)
    store.players.pop(int(tg_id), None)
    store.save()
    return _done(store, actor, source, "Удалил игрока", _who(p))


def wipe_players(store, actor, source="panel"):
    require(actor, "del_players")
    n = len(store.players)
    store.wipe_players()
    return _done(store, actor, source, "Удалил всех игроков", "", f"было {n}")


def teleport(store, actor, tg_id, loc, x, y, source="panel"):
    require(actor, "edit_players")
    p = _target(store, tg_id)
    p.loc, p.x, p.y = int(loc), int(x), int(y)
    p.combat = {}
    store.save_player(p)
    where = data.LOCATIONS[p.loc][0] if p.loc < len(data.LOCATIONS) else "?"
    queue(store, p.tg_id, f"🌀 Тебя переместили: <b>{where}</b> [{p.x},{p.y}]")
    return _done(store, actor, source, "Телепорт", _who(p), f"{where} [{p.x},{p.y}]")


# ── доступы ─────────────────────────────────────────────────

def grant(store, actor, tg_id, rank="viewer", caps=None, source="panel"):
    require(actor, "grant_admin")
    from engine import adminbot
    p = _target(store, tg_id)
    keep = bool(p.web_admin_password)
    text = adminbot.grant(store, p, rank, caps, reset_password=not keep)
    queue(store, p.tg_id, text)
    _done(store, actor, source, "Выдал доступ", _who(p),
          permissions.rank_title(p.web_admin_role))
    return True, text


def revoke(store, actor, tg_id, source="panel"):
    require(actor, "grant_admin")
    from engine import adminbot
    p = _target(store, tg_id)
    text = adminbot.revoke(store, p)
    queue(store, p.tg_id, text)
    _done(store, actor, source, "Отозвал доступ", _who(p))
    return True, text


def new_password(store, actor, tg_id, source="panel"):
    require(actor, "grant_admin")
    p = _target(store, tg_id)
    p.web_admin_password = permissions.new_password()
    store.save_player(p)
    queue(store, p.tg_id,
          f"🔑 Новый пароль от панели: <code>{p.web_admin_password}</code>")
    return _done(store, actor, source, "Сменил пароль доступа", _who(p))


# ── рассылка и мир ──────────────────────────────────────────

def broadcast(store, actor, text, source="panel"):
    require(actor, "broadcast")
    body = (text or "").strip()
    if not body:
        raise Denied("Пустое сообщение")
    skip = getattr(actor, "tg_id", 0) if actor is not None else 0
    queue_all(store, f"📣 <b>Объявление</b>\n\n{body}", skip=skip)
    n = len(store.players) - (1 if skip in store.players else 0)
    _done(store, actor, source, "Рассылка", f"{max(n, 0)} игрокам", body[:120])
    return True, max(n, 0)


def portal_open(store, actor, tpl_id, pick, source="panel"):
    """pick(store) -> ключ клетки для портала (выбор делает вызывающий)."""
    require(actor, "dungeons")
    tpl = _tpl(store, tpl_id)
    if tpl.get("portal_cell"):
        raise Denied("Портал уже открыт")
    key = pick(store)
    if not key:
        raise Denied("Нет подходящей клетки")
    c = store.world[key]
    c.name = f"🌀 Портал: {tpl['name']}"
    c.desc = (f"Врата сияют мистической энергией. Ведут в '{tpl['name']}' "
              f"(мин. уровень {tpl.get('min_level', 1)}).")
    c.tile = "cave"
    tpl["portal_cell"] = key
    import time
    tpl["opened_at"] = time.time()
    store.save()
    where = data.LOCATIONS[c.loc][0] if c.loc < len(data.LOCATIONS) else "?"
    queue_all(store, f"🌀 <b>Открылся портал!</b>\n\n{tpl['name']}\n"
                     f"📍 {where} [{c.x},{c.y}]")
    return _done(store, actor, source, "Открыл портал", tpl["name"],
                 f"{where} [{c.x},{c.y}]")


def portal_close(store, actor, tpl_id, source="panel"):
    require(actor, "dungeons")
    tpl = _tpl(store, tpl_id)
    key = tpl.get("portal_cell")
    if key:
        c = store.world.get(key)
        if c:
            c.name = "Заросшая поляна"
            c.desc = "Трава и кустарники. Здесь когда-то сиял портал."
            c.tile = "grass"
    tpl["portal_cell"] = None
    store.save()
    queue_all(store, f"🚪 Портал <b>{tpl['name']}</b> закрылся.")
    return _done(store, actor, source, "Закрыл портал", tpl["name"])


def _tpl(store, tpl_id):
    for t in store.settings.get("dungeon_templates", []) or []:
        if int(t["id"]) == int(tpl_id):
            return t
    raise Denied("Шаблон не найден")


def templates(store):
    return store.settings.get("dungeon_templates", []) or []


# ── операции над миром ──────────────────────────────────────
# Реализация переехала в engine/adminworld.py, но вызывать привычно
# через adminops — поэтому здесь тонкие делегаты.

def cataclysm_strike(store, actor, kind_key, loc=-1, hours=None, source="panel"):
    from engine import adminworld
    return adminworld.cataclysm_strike(store, actor, kind_key, loc, hours, source)


def cataclysm_end(store, actor, event_id, source="panel"):
    from engine import adminworld
    return adminworld.cataclysm_end(store, actor, event_id, source)


def cataclysm_calm(store, actor, source="panel"):
    from engine import adminworld
    return adminworld.cataclysm_calm(store, actor, source)


def boss_summon(store, actor, key, loc=None, hours=None, source="panel"):
    from engine import adminworld
    return adminworld.boss_summon(store, actor, key, loc, hours, source)


def boss_dismiss(store, actor, source="panel"):
    from engine import adminworld
    return adminworld.boss_dismiss(store, actor, source)

