    adminops.delete_player(store, p, tg_id, SRC)
    r = adminmenu.players(p, store, 0)
    r.alert = "Игрок удалён"
    return r


def _rank(p, store, rest):
    parts = str(rest).split(":")
    tg_id = _int(parts[0])
    rank = parts[1] if len(parts) > 1 else "viewer"
    adminops.grant(store, p, tg_id, rank, None, SRC)
    r = adminmenu.player_card(p, store, tg_id)
    r.alert = "Доступ выдан"
    return r


def _revoke(p, store, rest):
    tg_id = _int(rest)
    adminops.revoke(store, p, tg_id, SRC)
    r = adminmenu.player_card(p, store, tg_id)
    r.alert = "Доступ отозван"
    return r


def _newpass(p, store, rest):
    tg_id = _int(rest)
    adminops.new_password(store, p, tg_id, SRC)
    q = store.players.get(tg_id)
    r = adminmenu.player_card(p, store, tg_id)
    r.alert = f"Новый пароль: {q.web_admin_password}" if q else "Готово"
    return r


def _portal_open(p, store, rest):
    _, info = adminops.portal_open(store, p, _int(rest), adminmenu.pick_cell, SRC)
    r = adminmenu.portals(p, store)
    r.alert = f"Портал открыт: {info}"
    return r


def _portal_close(p, store, rest):
    adminops.portal_close(store, p, _int(rest), SRC)
    r = adminmenu.portals(p, store)
    r.alert = "Портал закрыт"
    return r


ROUTES = {
    "stats": _stats, "players": _players, "p": _card, "gift": _gift,
    "grant": _grant_menu, "portals": _portals, "content": _content,
    "audit": _audit, "cast": _cast, "castoff": _cast_off, "noop": _noop,
    "heal": _heal, "give": _give, "gold": _gold, "lvl": _level, "tp": _tp,
    "del": _del, "rank": _rank, "revoke": _revoke, "pass": _newpass,
    "popen": _portal_open, "pclose": _portal_close,
    "cata": _cata, "catahit": _cata_hit, "cataoff": _cata_off,
}

files.engine/itemui.py:
"""Общий вид списков предметов: нумерация, сетка кнопок, карточка.

Правило оформления: в списке кнопки несут только эмодзи — номер предмета
и его иконку. Что это за номер, написано в тексте сообщения. Подробности
и действия открываются по нажатию номера.
"""
from engine import data, rules

PER_PAGE = 10                     # ровно столько, сколько цифровых эмодзи
PER_ROW = 5

DIGITS = ["1️⃣", "2️⃣", "3️⃣", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"]

TYPES = {
    "weapon": ("⚔️", "Оружие"), "armor": ("🦺", "Броня"),
    "helmet": ("🪖", "Шлем"), "boots": ("👢", "Сапоги"),
    "accessory": ("💍", "Украшение"), "consumable": ("🧪", "Расходник"),
}

RARITY = {
    "common": ("⚪", "Обычный"), "uncommon": ("🟢", "Необычный"),
    "rare": ("🔵", "Редкий"), "epic": ("🟣", "Эпический"),
    "legendary": ("🟠", "Легендарный"),
}

BONUS = {
    "damage": ("⚔️", "Урон"), "defense": ("🛡", "Защита"),
    "hp": ("❤️", "Здоровье"), "mp": ("💙", "Мана"),
    "strength": ("💪", "Сила"), "agility": ("🏃", "Ловкость"),
    "intelligence": ("🧠", "Интеллект"), "endurance": ("🧱", "Выносливость"),
    "luck": ("🍀", "Удача"), "heal": ("❤️", "Лечит"),
    "mana": ("💙", "Даёт маны"),
}


def digit(n):
    """Эмодзи-номер позиции 1..10 (дальше — обычные цифры)."""
    return DIGITS[n - 1] if 1 <= n <= len(DIGITS) else f"{n}\ufe0f\u20e3"


def pages(total):
    return max(1, (total + PER_PAGE - 1) // PER_PAGE)


def clamp(page, total):
    return max(0, min(int(page or 0), pages(total) - 1))


def slice_page(items, page):
    """Кусок списка страницы: [(номер на странице, позиция в списке, элемент)]."""
    page = clamp(page, len(items))
    start = page * PER_PAGE
    chunk = items[start:start + PER_PAGE]
    return [(i + 1, start + i, it) for i, it in enumerate(chunk)], page


def grid(entries, action):
    """Сетка кнопок: только номер и иконка предмета, без подписей."""
    rows, row = [], []
    for num, pos, idx in entries:
        row.append((f"{digit(num)}{rules.item(idx)['icon']}", f"{action}:{pos}"))
        if len(row) == PER_ROW:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    return rows


def pager(page, total, action):
    """Строка перелистывания. Пустая, если страница одна."""
    last = pages(total)
    if last <= 1:
        return []
    row = []
    row.append(("⬅️", f"{action}:{page - 1}") if page > 0 else ("▪️", "noop"))
    row.append((f"{page + 1}/{last}", "noop"))
    row.append(("➡️", f"{action}:{page + 1}") if page < last - 1 else ("▪️", "noop"))
    return [row]


def bonus_lines(it):
    out = []
    for k, v in it["bonus"].items():
        icon, label = BONUS.get(k, ("•", k))
        out.append(f"{icon} {label} <b>+{v}</b>")
    return "\n".join(out) or "<i>Без бонусов</i>"


def type_label(it):
    icon, label = TYPES.get(it["type"], ("📦", it["type"]))
    dot, rare = RARITY.get(it["rarity"], ("⚪", it["rarity"]))
    return f"{icon} {label} · {dot} {rare}"


def line(num, idx, note=""):
    """Строка списка в тексте сообщения."""
    it = rules.item(idx)
    tail = f" · {note}" if note else ""
    return f"{digit(num)} {it['icon']} <b>{it['name']}</b>{tail}"


def card(idx, extra=""):
    """Шапка карточки предмета: имя, тип, бонусы."""
    it = rules.item(idx)
    body = (f"{it['icon']} <b>{it['name']}</b>\n"
            f"{type_label(it)}\n\n"
            f"{bonus_lines(it)}")
    return body + (f"\n\n{extra}" if extra else "")


def price_of(idx):
    return rules.item(idx)["price"]


def resale_of(idx):
    return max(1, rules.item(idx)["price"] // 2)


def wearable(it):
    return it["type"] in rules.SLOTS


def stock():
    """Ассортимент лавки — все предметы игры."""
    return list(range(len(data.ITEMS)))

files.engine/stash.py:
"""Два инвентаря: сумка теряется при смерти, защищённый карман — нет.

Как в Таркове: игрок сам решает, что взять «в рейд» риском, а что убрать
в безопасное место. Карман намеренно **меньше** сумки — иначе выбора нет,
все бы просто прятали всё.

  🎒 **Сумка** (`p.inventory`) — безразмерная, но при гибели часть вещей
     выпадает в надгробие вместе с золотом.
  🔒 **Карман** (`p.stash`) — вмещает `SLOTS` предметов, при смерти цел.
     VIP расширяет его на `VIP_BONUS` ячеек — это удобство, а не сила:
     карман не даёт статов и не влияет на бой.

Перекладывать можно только в безопасной локации: иначе игрок прятал бы
добычу прямо перед смертью и риск исчезал бы.
"""
import time

from engine import data, itemui, rules, slots
from engine.models import Reply

# Значения по умолчанию. Живые настройки лежат в settings и правятся из
# панели — см. tune(); константы остаются запасным вариантом, когда store
# недоступен (например, в чистых расчётах и тестах движка).
SLOTS = 5                    # базовый размер защищённого кармана
VIP_BONUS = 3                # сколько ячеек добавляет VIP
LOSS_SHARE = 0.5             # какая доля сумки выпадает при гибели
VIP_DAYS = 30                # срок VIP по умолчанию при выдаче из панели
SAFE_TYPES = ("safe",)       # где можно перекладывать

# ключ настройки -> (значение по умолчанию, подпись, пояснение)
TUNABLES = {
    "stash_slots": (SLOTS, "🔒 Ячеек в кармане",
                    "сколько вещей переживает гибель у обычного героя"),
    "stash_vip_bonus": (VIP_BONUS, "👑 Прибавка VIP",
                        "на сколько ячеек VIP расширяет карман"),
    "stash_loss_share": (LOSS_SHARE, "💀 Доля потерь сумки",
                         "какая часть сумки выпадает при смерти (0–1)"),
    "vip_days": (VIP_DAYS, "📅 Срок VIP, дней",
                 "на сколько дней выдаётся VIP кнопкой в панели"),
}


def tune(store, key):
    """Настройка из панели или значение по умолчанию."""
    default = TUNABLES[key][0]
    if store is None:
        return default
    raw = store.settings.get(key)
    if raw is None or raw == "":
        return default
    try:
        val = float(raw)
    except (TypeError, ValueError):
        return default
    if key == "stash_loss_share":
        return max(0.0, min(1.0, val))
    return max(0, int(val))


def set_tunables(store, values):
    """Сохранить настройки кармана и VIP. Пустое — вернуть умолчание."""
    for key in TUNABLES:
        if key not in values:
            continue
        raw = values[key]
        if raw is None or str(raw).strip() == "":
            store.settings.pop(key, None)
            continue
        try:
            val = float(raw)
        except (TypeError, ValueError):
            continue
        if key == "stash_loss_share":
            store.settings[key] = max(0.0, min(1.0, val))
        else:
            store.settings[key] = max(0, int(val))
    store.save()


# ── VIP ─────────────────────────────────────────────────────

def is_vip(p):
    """Активен ли VIP: бессрочный или ещё не истёкший."""
    if not getattr(p, "is_vip", False):
        return False
    until = float(getattr(p, "vip_until", 0) or 0)
    return until <= 0 or time.time() < until


def vip_left_days(p):
    until = float(getattr(p, "vip_until", 0) or 0)
    if not is_vip(p) or until <= 0:
        return 0
    return max(0, int((until - time.time()) // 86400) + 1)


def grant_vip(p, days=0):
    """Выдать VIP. days=0 — бессрочно."""
    p.is_vip = True
    p.vip_until = (time.time() + days * 86400) if days else 0.0


def vip_days(store):
    """Срок VIP при выдаче из панели."""
    return tune(store, "vip_days")


def revoke_vip(p):
    p.is_vip = False
    p.vip_until = 0.0
    p.offline_protected = False


def offline_protected(p):
    """Полная защита VIP от игровых воздействий на время выхода."""
    return is_vip(p) and bool(getattr(p, "offline_protected", False))


def set_offline(p, enabled):
    if enabled and not is_vip(p):
        return False, "Режим «Я офлайн» доступен только VIP."
    if enabled and p.combat:
        return False, "Сначала закончи бой."
    p.offline_protected = bool(enabled)
    return True, ("Ты офлайн. VIP-защита включена." if enabled
                  else "Ты снова в мире.")


# ── размер кармана ──────────────────────────────────────────

def capacity(p, store=None):
    """Сколько ячеек в защищённом кармане у этого героя.

    `store` необязателен: без него берутся значения по умолчанию, поэтому
    старые вызовы продолжают работать.
    """
    base = tune(store, "stash_slots")
    return base + (tune(store, "stash_vip_bonus") if is_vip(p) else 0)


def free_slots(p, store=None):
    return max(0, capacity(p, store) - len(getattr(p, "stash", None) or []))


def _stash(p):
    lst = getattr(p, "stash", None)
    if not isinstance(lst, list):
        lst = []
        p.stash = lst
    return lst


# ── где можно перекладывать ─────────────────────────────────

def safe_here(p):
    """Можно ли сейчас трогать карман: только в безопасных землях."""
    if p.loc >= len(data.LOCATIONS):
        return False
    return data.LOCATIONS[p.loc][2] in SAFE_TYPES


def _need_safe():
    return Reply(alert="Карман открывается только в безопасных землях — "
                       "загляни в Погост.")


# ── перекладывание ──────────────────────────────────────────

def put(p, arg, store=None):
    """Убрать предмет из сумки в защищённый карман."""
    if not safe_here(p):
        return _need_safe()
    pos = int(arg)
    if pos < 0 or pos >= len(p.inventory):
        return Reply(alert="Предмет не найден.")
    if free_slots(p, store) <= 0:
        return Reply(alert=f"Карман полон: {capacity(p, store)} ячеек. "
                           f"Освободи место или расширь VIP-статусом.")
    # Уходит КОНКРЕТНАЯ вещь: если спрятали вторую копию надетой, слот
    # остаётся занятым (раньше экипировка снималась по совпадению индекса).
    idx = slots.take_at(p, pos)
    it = rules.item(idx)
    _stash(p).append(idx)
    r = view(p, store=store)
    r.alert = f"🔒 В карман: {it['name']}"
    return r


def take(p, arg, store=None):
    """Достать предмет из кармана обратно в сумку."""
    if not safe_here(p):
        return _need_safe()
    pos = int(arg)
    lst = _stash(p)
    if pos < 0 or pos >= len(lst):
        return Reply(alert="Предмет не найден.")
    idx = lst.pop(pos)
    p.inventory.append(idx)
    r = view(p, store=store)
    r.alert = f"🎒 В сумку: {rules.item(idx)['name']}"
    return r


# ── потери при гибели ───────────────────────────────────────

def drop_on_death(p, rng=None, store=None):
    """Что выпадает из сумки при смерти. Возвращает список индексов.

    Карман не трогаем — в этом весь смысл. Надетое тоже остаётся: снимать
    с трупа собственную экипировку было бы слишком жестоко для казуальной
    игры, а риск и так есть.
    """
    import random

    rng = rng or random
    # Иммунитет получает только надетая ВЕЩЬ, а не любая с тем же индексом:
    # раньше дубликат надетого меча никогда не выпадал в надгробие.
    worn_at = slots.equipped_positions(p)
    losable = [i for i in range(len(p.inventory)) if i not in worn_at]
    if not losable:
        return []
    count = max(1, int(len(losable) * tune(store, "stash_loss_share")))
    lost_pos = sorted(rng.sample(losable, min(count, len(losable))), reverse=True)
    lost = []
    for pos in lost_pos:              # с конца, поэтому позиции не съезжают
        lost.append(slots.take_at(p, pos))
    return lost


# ── экраны ──────────────────────────────────────────────────

def view(p, page=0, store=None):
    """Экран кармана: что защищено, что можно убрать, сколько места."""
    lst = _stash(p)
    cap = capacity(p, store)
    vip_note = ""
    if is_vip(p):
        days = vip_left_days(p)
        vip_note = (f" · 👑 VIP +{tune(store, 'stash_vip_bonus')}"
                    + (f" ({days} дн.)" if days else " (бессрочно)"))

    lines = [f"🔒 <b>Защищённый карман</b> — {len(lst)}/{cap}{vip_note}", ""]
    if lst:
        for n, idx in enumerate(lst, 1):
            lines.append(itemui.line(n, idx, itemui.type_label(rules.item(idx))))
    else:
        lines.append("<i>Пусто. Всё, что здесь лежит, переживёт твою смерть.</i>")

    lines.append("")
    if safe_here(p):
        lines.append("<i>Нажми номер, чтобы достать вещь обратно в сумку.</i>")
    else:
        lines.append("⚠️ <i>Перекладывать можно только в безопасных землях.</i>")
    if not is_vip(p):
        big = tune(store, "stash_slots") + tune(store, "stash_vip_bonus")
        lines.append(f"<i>👑 VIP расширяет карман до {big} ячеек.</i>")

    rows = []
    if safe_here(p) and lst:
        entries = [(n, n - 1, idx) for n, idx in enumerate(lst, 1)]
        rows = itemui.grid(entries, "stake")
    rows.append([("🎒 Сумка", "bag"), ("◀️ Меню", "menu")])
    return Reply(text="\n".join(lines), keyboard=rows)


def death_note(lost, kept):
    """Строка для экрана гибели: что потеряно, что уцелело."""
    parts = []
    if lost:
        names = ", ".join(rules.item(i)["name"] for i in lost[:4])
        more = f" и ещё {len(lost) - 4}" if len(lost) > 4 else ""
        parts.append(f"🎒 Выпало из сумки: <b>{len(lost)}</b> — {names}{more}")
    if kept:
        parts.append(f"🔒 В кармане уцелело: <b>{kept}</b>")
    return "\n".join(parts)

files.engine/homestead.py:
"""Дом героя: якорь, сундук и отдых у очага (IDEAS-next, пункт 8).

Чем дом отличается от защищённого кармана (engine/stash.py): карман дают
всем и он открывает руки в любых безопасных землях — зато вмещает горстку.
Дом покупается один раз, хранит на порядок больше, но и доступ к нему
домашний: сундук привязан к поселению, где герой осел, и открыть его
можно только стоя у своих дверей. В этом и смысл «якоря»: трофеи нужно
куда-то нести, а дорога домой — это план на вечер.

Числа здесь — единый источник для обоих стеков: core/homestead.py
импортирует RULES, поэтому цены и лечение не разъедутся (тот же приём,
что у осад: engine/siege.py).
"""
from engine.models import Reply

RULES = {
    # уровень -> цена въезда/надстройки в бронзе и ячеек сундука.
    # 0-й уровень — дома нет: ночуем у костра на общих условиях.
    "cost": {1: 1500, 2: 6000, 3: 15000},
    "slots": {1: 12, 2: 24, 3: 40},
    "vip_bonus": 12,            # 👑 второй этаж
    "rest_share": {1: 0.5, 2: 2 / 3, 3: 1.0},   # доля HP/MP у очага
    "camp_share": 1 / 3,        #   у костра — как всегда
    "max_level": 3,
}

LEVEL_TITLES = {1: "🛖 Избушка", 2: "🏠 Дом", 3: "🏰 Палаты"}


# ── чистые правила (примитивы — их переиспользует сервер) ──

def capacity(level: int, vip: bool = False) -> int:
    base = RULES["slots"].get(int(level), 0)
    return base + (RULES["vip_bonus"] if base and vip else 0)


def upgrade_cost(level: int):
    """Сколько стоит следующий уровень; None — выше только небо."""
    nxt = int(level) + 1
    return RULES["cost"].get(nxt) if nxt <= RULES["max_level"] else None


def rest_share(level: int, at_home: bool, vip: bool = False) -> float:
    if not at_home or int(level) <= 0:
        return RULES["camp_share"]
    return 1.0 if vip else RULES["rest_share"].get(int(level), RULES["camp_share"])


def rest_amount(max_value: int, share: float) -> int:
    """Сколько восстановить. У костра — прежнее целочисленное деление,
    чтобы правка не поменяла ни одного старого боя; дома — по доле."""
    if share <= RULES["camp_share"] + 1e-9:
        return max(1, int(max_value) // 3)
    return max(1, min(int(max_value), int(round(int(max_value) * share))))


# ── браузерный герой ───────────────────────────────────────

def settled(p) -> bool:
    return int(getattr(p, "house_level", 0) or 0) > 0


def home_loc(p) -> int:
    # именно `is None`, а не `or -1`: нулевая локация — жилая
    raw = getattr(p, "home_loc", -1)
    return -1 if raw is None else int(raw)


def at_home(p) -> bool:
    """Дома ли герой: дом привязан к локации, где он осел."""
    return settled(p) and home_loc(p) == int(p.loc)


def is_vip(p) -> bool:
    """VIP считаем так же, как у кармана: второй этаж — его привилегия."""
    from engine import stash
    return stash.is_vip(p)


def cap_of(p) -> int:
    return capacity(int(p.house_level or 0) if settled(p) else 0, is_vip(p))


def free(p) -> int:
    return max(0, cap_of(p) - len(_chest(p)))


def can_put(p) -> bool:
    """Кнопка «убрать домой» на карточке вещи: только стоя у своих дверей."""
    return at_home(p) and free(p) > 0


def safe_here(p):
    from engine import stash
    return stash.safe_here(p)


def _chest(p):
    lst = getattr(p, "home", None)
    if not isinstance(lst, list):
        lst = []
        p.home = lst
    return lst


# ── действия ────────────────────────────────────────────────

def settle(p, store):
    """Осесть: одна бронза, и у героя появляется адрес."""
    from engine import currency
    if settled(p):
        return Reply(alert="Дом у тебя уже есть — загляни в него.")
    if not safe_here(p):
        return Reply(alert="Оситься можно только в безопасных землях. "
                           "Погост подойдёт.")
    cost = RULES["cost"][1]
    if not currency.deduct_currency(p, cost):
        return Reply(alert=f"На въезд не хватает: нужно {cost}🟤.")
    p.house_level = 1
    p.home_loc = int(p.loc)
    _save(store, p)
    r = screen(store, p)
    r.alert = "🏠 Ты осел. Сундук переживёт что угодно — дома."
    return r


def upgrade(p, store):
    from engine import currency
    if not settled(p):
        return Reply(alert="Сначала оседляйся.")
    cost = upgrade_cost(p.house_level)
    if cost is None:
        return Reply(alert="Дальше только башня. Это предел.")
    if not currency.deduct_currency(p, cost):
        return Reply(alert=f"На надстройку нужно {cost}🟤.")
    p.house_level = int(p.house_level) + 1
    _save(store, p)
    r = screen(store, p)
    r.alert = f"⬆️ {LEVEL_TITLES[p.house_level]} — места больше!"
    return r


def put(p, pos, store=None):
    """Сумка → домашний сундук. Только дома, иначе это был бы карман."""
    from engine import slots
    if not at_home(p):
        return Reply(alert="Сундук стоит дома — зайди в свои двери.")
    if free(p) <= 0:
        return Reply(alert=f"Сундук полон: {cap_of(p)} ячеек.")
    pos = int(pos)
    if pos < 0 or pos >= len(p.inventory):
        return Reply(alert="Предмет не найден.")
    idx = slots.take_at(p, pos)
    _chest(p).append(idx)
    if store is not None:
        _save(store, p)
    from engine import rules
    return Reply(alert=f"🏠 В сундук: {rules.item(idx)['name']}")


def take(p, pos, store=None):
    """Сундук → сумка."""
    if not at_home(p):
        return Reply(alert="Сундук дома — там и открывают.")
    pos = int(pos)
    chest = _chest(p)
    if pos < 0 or pos >= len(chest):
        return Reply(alert="Такой вещи в сундуке нет.")
    from engine import rules
    idx = chest.pop(pos)
    p.inventory.append(idx)
    if store is not None:
        _save(store, p)
    return Reply(alert=f"🎒 В сумке снова: {rules.item(idx)['name']}")


def _save(store, p):
    if store is not None:
        store.save_player(p)


def rest_note(p) -> str:
    """Строчка для экрана отдыха: очаг или костёр."""
    return ("<i>🔥 Дом отдыхает лучше каменных стен: лечит сильнее.</i>"
            if at_home(p) else "")


# ── витрина браузера ────────────────────────────────────────

def button(store, p, rows):
    """Строка на экран клетки: войти в дом или осесть (как делали осады)."""
    if settled(p) and at_home(p):
        rows.insert(0, [(f"🏠 Дом · сундук {len(_chest(p))}/{cap_of(p)}",
                         "house")])
    elif not settled(p) and safe_here(p):
        rows.insert(0, [(f"🏠 Оселиться здесь ({RULES['cost'][1]}🟤)",
                         "house:buy")])


def screen(store, p):
    from engine import itemui, rules
    if not settled(p):
        lines = ["🏠 <b>Дом героя</b>", "",
                 "Своего порога у тебя пока нет.",
                 "<i>Оситься можно в безопасных землях: сундук переживёт"
                 " смерть, отдых у очага лечит сильнее, а соседей по"
                 " поселению видно каждый день.</i>"]
        rows = []
        if safe_here(p):
            rows.append([(f"🏠 Оселиться ({RULES['cost'][1]}🟤)", "house:buy")])
        rows.append([("◀️ В мир", "world")])
        return Reply(text="\n".join(lines), keyboard=rows)

    level = int(p.house_level)
    cap = cap_of(p)
    chest = _chest(p)
    lines = [f"{LEVEL_TITLES.get(level, '🏠 Дом')} <b>Дом героя</b>", "",
             f"📦 Сундук: <b>{len(chest)}/{cap}</b>"
             + (f" · 👑 второй этаж +{RULES['vip_bonus']}" if is_vip(p) else "")]
    note = upgrade_cost(level)
    lines.append(f"⬆️ Надстройка: <b>{note}🟤</b>" if note
                 else "⬆️ Выше только звёзды — это предел.")
    lines.append("")
    if chest:
        for n, idx in enumerate(chest, 1):
            lines.append(itemui.line(n, idx, itemui.type_label(rules.item(idx))))
        lines.append("<i>Нажми номер, чтобы вернуть вещь в сумку.</i>")
    else:
        lines.append("<i>Сундук пуст. Всё, что здесь ляжет, — переживёт всё.</i>")

    entries = [(n, n - 1, idx) for n, idx in enumerate(chest, 1)]
    rows = itemui.grid(entries, "house:take") if entries else []
    if note:
        rows.append([(f"⬆️ Надстроить ({note}🟤)", "house:up")])
    rows.append([("🏕 Отдых у очага", "rest")])
    rows.append([("◀️ В мир", "world")])
    return Reply(text="\n".join(lines), keyboard=rows)


def play(store, p, arg=""):
    """Единая точка входа колбэков «house:*» (роутер game.py)."""
    if arg == "buy":
        return settle(p, store)
    if arg == "up":
        return upgrade(p, store)
    if arg.startswith("put:"):
        put(p, arg[4:], store=store)
        return screen(store, p)
    if arg.startswith("take:"):
        take(p, arg[5:], store=store)
        return screen(store, p)
    return screen(store, p)

files.engine/dungeon.py:
"""Подземелья для браузерного стека: портал наконец ведёт внутрь.

Раньше `portal_cell` был чистой декорацией — админ открывал портал, на
карте появлялся 🌀, игрокам уходила весть, а войти было некуда. Серверный
бот (`bot/handlers/dungeon.py`) подземелья умел, браузерный — нет.

Здесь та же модель, что на сервере, но в терминах `engine`:
  • «забег» (`run`) живёт у игрока в `p.dungeon` — шаблон, сид, этаж, где
    стоит и что уже зачищено;
  • сетка **не хранится**, а восстанавливается из сида по требованию, так
    что сохранение не пухнет от сотен клеток;
  • изменения (убитая тварь, вскрытый сундук) держим списком ключей.

Выход — клетка входа: пришёл своим ходом, вышел своим ходом. Смерть внутри
выбрасывает наружу, как обычная гибель.
"""
import random

from engine import currency, data, itemui, rules
from engine.models import Reply

SIZE_DEFAULT = 10
FLOOR_TILES = ("cave", "road", "grass")
EXIT = (0, 0)                # клетка выхода — всегда угол

# Куски описаний: подземелье должно читаться, а не быть сеткой букв.
ROOMS = [
    ("Сырой коридор", "Со стен капает. Эхо шагов уходит слишком далеко."),
    ("Обвалившийся зал", "Потолок просел, из завала торчат балки."),
    ("Костница", "Черепа сложены в стены аккуратными рядами."),
    ("Затопленная галерея", "Вода по щиколотку и пахнет железом."),
    ("Зал с колоннами", "Колонны уходят во тьму, конца им не видно."),
    ("Келья", "Кто-то жил здесь добровольно. Это хуже всего."),
    ("Склад", "Ящики вскрыты, содержимое растащили давно."),
    ("Алтарная", "На камне бурые пятна, которые никто не смыл."),
    ("Провал", "Пол обрывается в темноту. Дна не слышно."),
    ("Тупик", "Дальше только стена. И царапины на ней."),
]


# ── доступ к шаблонам ───────────────────────────────────────

def templates(store):
    return store.settings.get("dungeon_templates", []) or []


def template(store, tpl_id):
    for t in templates(store):
        if int(t["id"]) == int(tpl_id):
            return t
    return None


def portal_at(store, key):
    """Шаблон, чей портал открыт в этой клетке (или None)."""
    for t in templates(store):
        if t.get("portal_cell") == key:
            return t
    return None


# ── забег ───────────────────────────────────────────────────

def run_of(p):
    r = getattr(p, "dungeon", None)
    return r if isinstance(r, dict) and r else None


def inside(p):
    return run_of(p) is not None


def size_of(tpl):
    try:
        return max(5, min(20, int(tpl.get("grid_size", SIZE_DEFAULT))))
    except (TypeError, ValueError):
        return SIZE_DEFAULT


def enter(store, p):
    """Войти в портал под ногами."""
    if inside(p):
        return view(store, p)
    key = f"{p.loc}:{p.x}:{p.y}"
    tpl = portal_at(store, key)
    if tpl is None:
        return Reply(alert="Здесь нет портала.")
    if p.level < int(tpl.get("min_level", 1)):
        return Reply(alert=f"Нужен {tpl['min_level']} уровень, у тебя {p.level}.")

    p.dungeon = {
        "tpl": int(tpl["id"]),
        "seed": random.randint(1, 1_000_000),
        "floor": 1,
        "x": EXIT[0], "y": EXIT[1],
        "back": [int(p.loc), int(p.x), int(p.y)],   # куда вернуть на выходе
        "cleared": [], "looted": [], "seen": [],
    }
    store.save_player(p)
    r = view(store, p)
    r.alert = f"Ты входишь в «{tpl['name']}»"
    return r


def leave(store, p, reason=""):
    """Выйти наружу: вернуть игрока к порталу."""
    run = run_of(p)
    if run is None:
        return Reply(alert="Ты не в подземелье.")
    back = run.get("back") or [0, 5, 5]
    p.loc, p.x, p.y = int(back[0]), int(back[1]), int(back[2])
    p.dungeon = {}
    store.save_player(p)
    text = reason or "🚪 Ты выбираешься наружу. Свежий воздух непривычен."
    return Reply(text=text, keyboard=[[("🧭 В мир", "world")], [("◀️ Меню", "menu")]])


def bail_out(store, p):
    """Аварийный выход: зовётся при гибели внутри подземелья."""
    run = run_of(p)
    if run is None:
        return
    p.dungeon = {}


# ── процедурная сетка ───────────────────────────────────────

def _cell_rng(run, x, y):
    """Своя случайность на клетку — сетка не хранится, а выводится."""
    return random.Random(run["seed"] * 7919 + run["floor"] * 104729
                         + x * 31 + y * 17)


def cell(store, p, x=None, y=None):
    """Описание клетки подземелья: восстанавливается из сида."""
    run = run_of(p)
    if run is None:
        return None
    tpl = template(store, run["tpl"]) or {}
    size = size_of(tpl)
    x = run["x"] if x is None else x
    y = run["y"] if y is None else y
    if not (0 <= x < size and 0 <= y < size):
        return None

    rng = _cell_rng(run, x, y)
    floor = int(run["floor"])
    key = f"{floor}:{x}:{y}"
    is_exit = (x, y) == EXIT
    # Выход стоит в углу: хотя бы два ближайших коридора обязаны быть
    # открыты, иначе иногда герой появлялся в комнате без единой кнопки
    # движения и подземелье выглядело зависшим.
    entry_corridor = (x, y) in {(0, 1), (1, 0)}
    wall = (not is_exit and not entry_corridor) and rng.random() < 0.20

    name, desc = ROOMS[rng.randrange(len(ROOMS))]
    mob = (not wall and not is_exit and rng.random() < 0.22
           and key not in (run.get("cleared") or []))
    chest = (not wall and not is_exit and rng.random() < 0.12
             and key not in (run.get("looted") or []))
    stairs = (not wall and not is_exit and rng.random() < 0.04)

    return {
        "x": x, "y": y, "key": key, "name": name, "desc": desc,
        "wall": wall, "exit": is_exit, "mob": mob, "chest": chest,
        "stairs": stairs, "size": size, "floor": floor,
        "mob_level": max(1, int(tpl.get("min_level", 1)) + floor - 1
                         + rng.randrange(0, 3)),
    }


def _passable(store, p, x, y):
    c = cell(store, p, x, y)
    return c is not None and not c["wall"]


# ── перемещение ─────────────────────────────────────────────

DIRS = {"n": (-1, 0), "s": (1, 0), "w": (0, -1), "e": (0, 1)}
ARROWS = {"n": "⬆️", "s": "⬇️", "w": "⬅️", "e": "➡️"}


def move(store, p, direction):
    run = run_of(p)
    if run is None:
        return Reply(alert="Ты не в подземелье.")
    dx, dy = DIRS.get(direction, (0, 0))
    nx, ny = run["x"] + dx, run["y"] + dy
    if not _passable(store, p, nx, ny):
        return Reply(alert="Там глухая стена.")
    run["x"], run["y"] = nx, ny
    seen = run.setdefault("seen", [])
    key = f"{run['floor']}:{nx}:{ny}"
    if key not in seen:
        seen.append(key)
    store.save_player(p)

    c = cell(store, p)
    if c and c["mob"]:                       # твари нападают сами
        return fight(store, p)
    return view(store, p)


def descend(store, p):
    """Спуск на следующий этаж: глубже — опаснее и прибыльнее."""
    run = run_of(p)
    c = cell(store, p) if run else None
    if not c or not c["stairs"]:
        return Reply(alert="Здесь нет спуска.")
    run["floor"] = int(run["floor"]) + 1
    run["x"], run["y"] = EXIT
    run["seen"] = []
    store.save_player(p)
    r = view(store, p)
    r.alert = f"Ты спускаешься на этаж {run['floor']}"
    return r


# ── содержимое клеток ───────────────────────────────────────

def fight(store, p):
    """Бой с обитателем подземелья — через обычную боевую систему."""
    from engine import combat

    run = run_of(p)
    c = cell(store, p) if run else None
    if not c or not c["mob"]:
        return Reply(alert="Здесь пусто.")
    run.setdefault("cleared", []).append(c["key"])
    store.save_player(p)
    idx = _mob_for(c["mob_level"])
    return combat.start(p, idx, store=store)


def _mob_for(level):
    """Тварь по уровню: берём ближайшую по силе из бестиария."""
    best, gap = 0, None
    for i, m in enumerate(data.MOBS):
        d = abs(int(m[2]) - int(level))
        if gap is None or d < gap:
            best, gap = i, d
    return best


def open_chest(store, p):
    run = run_of(p)
    c = cell(store, p) if run else None
    if not c or not c["chest"]:
        return Reply(alert="Сундука здесь нет.")
    run.setdefault("looted", []).append(c["key"])

    floor = int(run["floor"])
    gold = random.randint(15, 45) + floor * 12
    currency.earn(p, gold)
    lines = [f"📦 <b>Сундук подземелья</b>\n\nВнутри: {gold} 🪙"]

    if random.random() < 0.6:
        from engine import items
        idx = _loot_for(p)
        p.inventory.append(idx)
        inst = items.create(store, idx, source="dungeon", owner=p.tg_id,
                            luck=p.luck, detail=f"этаж {floor}")
        it = rules.item(idx)
        name = items.title(inst) if inst else it["name"]
        lines.append(f"🕳 Добыча: {it['icon']} <b>{name}</b>")

    from engine import factions
    lines.extend(factions.award(store, p, "chest_opened"))
    store.save_player(p)
    r = view(store, p)
    r.text = "\n".join(lines) + "\n\n" + r.text
    return r


def _loot_for(p):
    pool = [i for i, it in enumerate(data.ITEMS) if it[3] <= 40 + p.level * 30]
    return random.choice(pool or range(len(data.ITEMS)))


# Экраны живут в engine/dungeonui.py — здесь только правила.

def view(store, p):
    from engine import dungeonui
    return dungeonui.view(store, p)


def minimap(store, p):
    from engine import dungeonui
    return dungeonui.minimap(store, p)

files.engine/dungeonui.py:
"""Экраны подземелья: комната, кнопки перемещения, карта этажа.

Отделено от engine/dungeon.py, где живут правила: генерация клеток,
перемещение и содержимое. Здесь только сборка Reply.
"""
from engine import rules
from engine.dungeon import (ARROWS, DIRS, EXIT, _passable, cell, leave,
                            run_of, size_of, template)
from engine.models import Reply


def view(store, p):
    """Главный экран подземелья: где стоишь, что вокруг, куда идти."""
    run = run_of(p)
    if run is None:
        return Reply(alert="Ты не в подземелье.")
    tpl = template(store, run["tpl"]) or {"name": "Подземелье"}
    c = cell(store, p)
    if c is None:
        return leave(store, p, "Подземелье схлопнулось за спиной.")

    lines = [f"🕳 <b>{tpl['name']}</b> · этаж {run['floor']}",
             f"📍 [{c['x']},{c['y']}] · <i>{c['name']}</i>", "",
             c["desc"], ""]
    here = []
    if c["exit"]:
        here.append("🚪 Выход наружу")
    if c["mob"]:
        here.append(f"👾 Обитатель (ур. {c['mob_level']})")
    if c["chest"]:
        here.append("📦 Сундук")
    if c["stairs"]:
        here.append("⬇️ Спуск глубже")
    lines.append("\n".join(here) if here else "<i>Пусто.</i>")
    lines.append(f"\n❤️ {p.hp}/{rules.stats(p, store)['max_hp']}  🪙 {p.gold}")

    rows = []
    nav = []
    for d in ("n", "s", "w", "e"):
        dx, dy = DIRS[d]
        if _passable(store, p, run["x"] + dx, run["y"] + dy):
            nav.append((ARROWS[d], f"dgo:{d}"))
        else:
            nav.append(("⬛", "dwall"))
    rows.append(nav)

    act = []
    if c["mob"]:
        act.append(("⚔️ Атаковать", "dfight"))
    if c["chest"]:
        act.append(("📦 Открыть", "dchest"))
    if act:
        rows.append(act)
    deep = []
    if c["stairs"]:
        deep.append(("⬇️ Спуститься", "ddown"))
    if c["exit"]:
        deep.append(("🚪 Выйти", "dexit"))
    if deep:
        rows.append(deep)
    rows.append([("🗺 Карта", "dmap"), ("🎒 Сумка", "bag")])
    return Reply(text="\n".join(lines), keyboard=rows)


def minimap(store, p):
    """Карта этажа: показываем только пройденное."""
    run = run_of(p)
    if run is None:
        return Reply(alert="Ты не в подземелье.")
    tpl = template(store, run["tpl"]) or {}
    size = size_of(tpl)
    seen = set(run.get("seen") or [])
    seen.add(f"{run['floor']}:{run['x']}:{run['y']}")

    rows = []
    for x in range(size):
        line = ""
        for y in range(size):
            key = f"{run['floor']}:{x}:{y}"
            if (x, y) == (run["x"], run["y"]):
                line += "🔴"
                continue
            if key not in seen:
                line += "⬜"
                continue
            c = cell(store, p, x, y)
            if c is None or c["wall"]:
                line += "⬛"
            elif c["exit"]:
                line += "🚪"
            elif c["mob"]:
                line += "👾"
            elif c["chest"]:
                line += "📦"
            elif c["stairs"]:
                line += "⬇️"
            else:
                line += "🟫"
        rows.append(line)

    text = (f"🗺 <b>Этаж {run['floor']}</b> · изучено "
            f"{len(seen)}/{size * size}\n\n" + "\n".join(rows)
            + "\n\n🔴 ты · ⬜ тьма · ⬛ стена · 🚪 выход · ⬇️ спуск")
    return Reply(text=text, keyboard=[[("◀️ Назад", "dview")]])

