    # ── мир ─────────────────────────────────────────────────
    def _cell(self, p):
        return world.cell_at(self.world, p.loc, p.x, p.y, getattr(p, "floor", 0))

    def do_world(self, p, arg=""):
        if not p.created_char:
            return Reply(alert="Сначала создай героя!")
        if p.combat:
            return combat.view(p)
        if social.in_dungeon(p):          # внутри подземелья свой мир
            return social.dungeon_view(self.store, p)
        cell = self._cell(p)
        if not cell:
            p.loc, p.x, p.y = 0, 5, 5
            cell = self._cell(p)
        mapview.mark_visited(p)
        ok = world.neighbours(self.world, p.loc, p.x, p.y, getattr(p, "floor", 0))
        rows = []
        for line in (("nw", "n", "ne"), ("w", None, "e"), ("sw", "s", "se")):
            row = []
            for d in line:
                if d is None:
                    row.append(("🔍", "look"))
                elif ok.get(d):
                    row.append((world.ARROWS[d], f"go:{d}"))
                else:
                    row.append(("⬛", "wall"))
            rows.append(row)
        # Единая лестничная площадка: сразу под стрелками показываем обе
        # доступные стороны. В браузерном стеке этажи — подуровни, поэтому
        # меньший номер означает подъём, больший — спуск.
        floor_buttons = []
        current_floor = getattr(p, "floor", 0)
        links = sorted(
            (tuple(link) for link in (cell.floor_links or ())),
            key=lambda link: (link[3] > current_floor, link[3]),
        )
        for link in links:
            target_floor = int(link[3])
            if target_floor < current_floor:
                label = f"🪜⬆️ Подняться: этаж {target_floor + 1}"
            else:
                label = f"🪜⬇️ Спуститься: этаж {target_floor + 1}"
            floor_buttons.append((label, f"floor:{target_floor}"))
        if floor_buttons:
            rows.append(floor_buttons)

        # Старые/обычные двери остаются одиночным переходом.
        if cell.link:
            rows.append([("🚪 Перейти через дверь", "transition")])
        rows.append([("🏕 Отдых", "rest"), ("🎒 Инвентарь", "bag")])
        rows.append([("🗺 Карта", "map"), ("◀️ Меню", "menu")])
        alarm = cataclysm.banner(self.store, p.loc)
        if alarm:
            rows.insert(0, [("🌋 Что происходит?", "disaster")])
        siege.button(self.store, p, rows)     # 🔥 вход в осаду под ногами
        homestead.button(self.store, p, rows)  # 🏠 свой порог виден сразу
        here = mapview.others_here(self.store, p, p.loc, p.x, p.y)
        reply = Reply(text=texts.cell_view(p, cell, alarm, here), keyboard=rows)
        if merchant.at(self.store, p.loc):
            reply.text = (f"🧳 <b>Здесь стоит {merchant.MERCHANT_NAME}!</b>\n\n"
                          + reply.text)
            reply.keyboard.append([("🧳 Торговец", "merchant")])
        return reply

